window.SITE_DATA={"lessons":[{"slug":"kto-takoy-iisus","title":"Кто такой Иисус?","n":1},{"slug":"est-li-bog","title":"Есть ли Бог?","n":2},{"slug":"chto-takoe-bibliya","title":"Что такое Библия?","n":3},{"slug":"kakoy-bog","title":"Какой Бог?","n":4},{"slug":"zachem-chelovek","title":"Зачем существует человек?","n":5},{"slug":"chto-takoe-greh","title":"Что такое грех?","n":6},{"slug":"posledstviya-greha","title":"Почему грех — это серьёзно?","n":7},{"slug":"obeshchanie","title":"Бог не отказался от человека","n":8},{"slug":"iisus-syn-bozhiy","title":"Почему Иисуса называют Богом?","n":9},{"slug":"krest","title":"Почему Иисус умер на кресте?","n":10},{"slug":"voskresenie","title":"Воскресение","n":11},{"slug":"blagodat","title":"Благодать","n":12},{"slug":"vera-i-pokayanie","title":"Вера и покаяние","n":13},{"slug":"chto-dalshe","title":"Новая жизнь: что дальше","n":14}],"glossary":{"angel":{"term":"Ангел","def":"Слово значит «вестник». Ангелы — духовные существа, которых создал Бог. Они служат Ему и иногда передают людям Его слова. Умершие люди ангелами не становятся."},"apostol":{"term":"Апостол","def":"Буквально «посланник». Так называют двенадцать ближайших учеников Иисуса, которых Он послал рассказывать о Нём, а также Павла. Их письма вошли в Новый Завет."},"bibliya":{"term":"Библия","def":"Собрание из 66 книг, которые писали разные люди на протяжении примерно полутора тысяч лет. Христиане верят, что через эти книги говорит Бог. Делится на Ветхий и Новый Завет."},"blagodat":{"term":"Благодать","def":"Доброта Бога, которую человек не заслужил и не может заслужить. Прощение и новая жизнь с Богом даются по благодати, то есть как подарок, а не как награда за хорошие дела."},"vera":{"term":"Вера","def":"В Библии вера — это не просто согласие с тем, что Бог существует, а доверие Ему. Верить в Иисуса значит полагаться на Него: на то, Кто Он и что Он сделал."},"vethiy-zavet":{"term":"Ветхий Завет","def":"Первая, большая часть Библии. Книги, написанные до рождения Иисуса: о сотворении мира, истории народа Израиля, законы, молитвы и пророчества. «Завет» значит «договор, союз»."},"vechnaya-zhizn":{"term":"Вечная жизнь","def":"Не просто жизнь, которая длится бесконечно, а жизнь с Богом. По словам Иисуса, она начинается уже сейчас, когда человек узнаёт Бога, и продолжается после смерти."},"voskresenie":{"term":"Воскресение","def":"Возвращение к жизни после смерти. Христиане верят, что Иисус на третий день после казни воскрес телесно, а не только «в памяти учеников». И что однажды воскреснут все люди."},"greh":{"term":"Грех","def":"Всё, чем человек нарушает волю Бога: поступки, слова, мысли и желания, а также доброе, которое он знал, что нужно сделать, но не сделал. В основе греха — отворачивание от Бога, желание жить так, будто Бог не нужен."},"evangelie":{"term":"Евангелие","def":"В переводе с греческого «добрая весть»: весть о том, что Бог через Иисуса Христа открыл людям путь к прощению и примирению с Собой. Евангелиями также называют четыре книги о жизни Иисуса: от Матфея, Марка, Луки и Иоанна."},"evangelskie-hristiane":{"term":"Евангельские христиане","def":"Так называют протестантов, для которых главное — личная вера в Иисуса, Библия как высший авторитет и рассказ другим о Евангелии. Это широкое движение: в него входят баптисты, пятидесятники и многие другие церкви. Авторы этого сайта — евангельские христиане."},"zhertva":{"term":"Жертва","def":"В Ветхом Завете люди приносили Богу в жертву животных. Это показывало: грех ведёт к смерти, но Бог может принять другую жизнь вместо жизни человека. Христиане верят, что Иисус стал последней жертвой. Он отдал Свою жизнь за людей, и больше жертвы не нужны."},"zavet":{"term":"Завет","def":"Союз, договор между Богом и людьми, в котором Бог даёт обещания. Отсюда названия двух частей Библии: Ветхий (старый) и Новый Завет."},"zakon":{"term":"Закон","def":"Так в Библии часто называют правила и заповеди, которые Бог дал народу Израиля через Моисея. Например, Десять заповедей. Ещё так называют первые пять книг Библии."},"zapoved":{"term":"Заповедь","def":"Указание Бога о том, как жить. Самые известные — десять заповедей. Иисус сказал, что главные заповеди — любить Бога всем сердцем и любить ближнего, как самого себя."},"izrail":{"term":"Израиль","def":"Народ, который произошёл от Авраама и с которым Бог заключил завет. Большая часть Ветхого Завета — история этого народа. Иисус по рождению был израильтянином, иудеем."},"iskuplenie":{"term":"Искупление","def":"Освобождение за выкуп. В Библии так описывают то, что сделал Иисус: Своей смертью Он освободил людей от власти греха и его последствий."},"krest":{"term":"Крест","def":"Орудие казни в Римской империи, самой мучительной и позорной. На кресте был казнён Иисус. Для христиан крест стал знаком того, что Иисус умер за людей."},"kreschenie":{"term":"Крещение","def":"Погружение в воду (или обливание водой) как знак того, что человек начинает новую жизнь с Иисусом. Иисус поручил Своим ученикам крестить тех, кто станет Его учениками. Христианские церкви по-разному понимают смысл крещения."},"messiya":{"term":"Мессия","def":"Обещанный Богом Спаситель и Царь, которого ждал народ Израиля. Слово еврейское, по-гречески оно звучит как «Христос». Значит «помазанник»."},"molitva":{"term":"Молитва","def":"Разговор с Богом. Можно говорить своими словами, о чём угодно: благодарить, просить, признаваться, спрашивать. Особые слова или место не обязательны."},"nagornaya-propoved":{"term":"Нагорная проповедь","def":"Самая известная речь Иисуса. Он произнёс её на склоне горы перед учениками и толпой. В ней прозвучали молитва «Отче наш» и слова «Не судите, и не будете судимы». Её записал Матфей в своём Евангелии."},"novyy-zavet":{"term":"Новый Завет","def":"Вторая часть Библии: книги, написанные после жизни Иисуса. Четыре Евангелия о Его жизни, история первых христиан и письма апостолов."},"pokayanie":{"term":"Покаяние","def":"Разворот жизни. Человек признаёт перед Богом, что был неправ, и поворачивается к Нему. Это не только сожаление, но и решение изменить направление."},"pravednost":{"term":"Праведность","def":"Быть правым перед Богом, жить так, как Он задумал. Своими силами праведным перед Богом не становится никто. Христиане верят, что Бог дарит праведность тем, кто доверился Иисусу: прощает их и принимает как Своих."},"predanie":{"term":"Предание","def":"Учение церкви, которое передаётся из поколения в поколение: решения древних церковных соборов, труды первых христианских учителей, обычаи. Православные и католики считают Предание важным наравне с Библией. Протестанты уважают его, но проверяют всё по Библии."},"primirenie":{"term":"Примирение","def":"Восстановление разрушенных отношений. В Библии так говорится о том, что через Иисуса Бог восстановил отношения людей с Собой."},"prichastie":{"term":"Причастие","def":"Хлеб и вино (или виноградный сок), которые христиане вместе едят и пьют в память о смерти Иисуса. Так велел Сам Иисус на последнем ужине с учениками. Ещё его называют евхаристией и вечерей Господней."},"prorok":{"term":"Пророк","def":"Человек, через которого Бог говорил к людям. Пророки призывали вернуться к Богу, а иногда говорили о будущем. Их книги составляют большую часть Ветхого Завета."},"protestanty":{"term":"Протестанты","def":"Одна из трёх главных ветвей христианства, вместе с православными и католиками. Появилась в XVI веке. Для протестантов главный авторитет — только Библия, а спасение — подарок, который принимают верой. К протестантам относятся лютеране, баптисты, пятидесятники, евангельские христиане и другие."},"proschenie":{"term":"Прощение","def":"Решение не взыскивать с человека за то, что он сделал плохого. Бог прощает тех, кто доверяется Иисусу: вина снимается, и отношения восстанавливаются."},"psalmy":{"term":"Псалмы","def":"Книга молитв и песен в Ветхом Завете. В ней 150 псалмов, многие написал царь Давид. В псалмах люди благодарят Бога, радуются, просят о помощи и даже жалуются Ему."},"reformatsiya":{"term":"Реформация","def":"Движение в XVI веке, когда Мартин Лютер и другие стали призывать церковь вернуться к Библии. Они учили, что главный авторитет — Библия, а спасение даётся по благодати через веру. Так появились протестантские церкви."},"svyatoy-duh":{"term":"Святой Дух","def":"Бог, Который действует в мире и в людях. Христиане верят, что Святой Дух живёт в каждом, кто доверился Иисусу: помогает понимать Бога, меняться и жить по-новому. Одно из Лиц Троицы."},"svyatost":{"term":"Святость","def":"Особая чистота и инаковость Бога: в Нём нет никакого зла, и Он отличается от всего, что Он создал. Свят — значит совершенно чист и «отделён» от зла."},"svyashchennoe-pisanie":{"term":"Священное Писание","def":"Другое название Библии. Так говорят, чтобы подчеркнуть: это особая книга, через неё говорит Бог. Во времена Иисуса Писанием называли книги Ветхого Завета."},"simvol-very":{"term":"Символ веры","def":"Короткий текст, где перечислено главное, во что верят христиане: о Боге Отце, Сыне и Святом Духе, о смерти и воскресении Иисуса. Самый известный — Никейский символ веры, его приняли в IV веке. С ним согласны православные, католики и большинство протестантов."},"spasenie":{"term":"Спасение","def":"Избавление от греха и его последствий и восстановление отношений с Богом. Христиане верят, что спасение даёт Бог через Иисуса, а человек принимает его верой."},"sud":{"term":"Суд","def":"Христиане верят, что Бог справедлив и что однажды каждый человек даст Ему отчёт за свою жизнь. Бог не делает вид, что зла нет."},"syn-bozhiy":{"term":"Сын Божий","def":"Так в Библии называют Иисуса. Это не значит, что Бог «родил» Его, как рождаются люди, или что Он младше Отца. Сын существует всегда, вместе с Отцом. Слово «Сын» говорит о самой близкой связи и о том, что Он одной природы с Богом Отцом."},"troitsa":{"term":"Троица","def":"Христиане верят в одного Бога, Который существует как Отец, Сын и Святой Дух. Это не три бога и не три «маски» одного, а один Бог в трёх Лицах. Само слово «Троица» в Библии не встречается, но христиане используют его, чтобы обобщить то, что Библия говорит о Боге."},"hristos":{"term":"Христос","def":"Это не фамилия Иисуса. Это Его звание. По-гречески «Христос» значит «Помазанник», то же, что еврейское слово «Мессия». Так называли Спасителя, Которого обещал Бог. «Иисус Христос» значит «Иисус — Мессия»."},"tsarstvo-bozhe":{"term":"Царство Божье","def":"Главная тема проповеди Иисуса. Это не страна на карте, а власть Бога: там, где Бога признают Царём, где Его воля исполняется. Царство уже началось с приходом Иисуса и полностью наступит в будущем."},"tserkov":{"term":"Церковь","def":"Прежде всего не здание, а люди: все, кто верит в Иисуса. А также конкретная община христиан, которые собираются вместе, чтобы молиться, читать Библию и поддерживать друг друга."}},"search":[{"title":"Кто такой Иисус?","url":"kto-takoy-iisus.html","kind":"Урок 1","text":"Бог, Который стал человеком. Его имя знает почти каждый. Годы на календаре мы считаем от Его рождения. Но кто Он? Христиане отвечают так: Иисус — не просто хороший человек и не только пророк. Он — Бог, Который пришёл к людям и стал одним из нас. Представьте, что автор книги вошёл в свою историю как один из героев. Он живёт среди своих персонажей, говорит с ними, и его можно узнать. Христиане верят, что Бог сделал именно это. Он был настоящим человеком Иисус не сказочный герой. Он жил около 2000 лет назад в Израиле, который тогда был частью Римской империи. Вырос в маленьком городке Назарете и работал плотником. Примерно в 30 лет начал","keys":"иисус христос историческая личность кто он иисус бог бог стал человеком кто такой иисус","pin":true},{"title":"Есть ли Бог?","url":"est-li-bog.html","kind":"Урок 2","text":"Христиане уверены, что да. Вот почему. Многие думают так: Бога никто не видел, значит, Его, скорее всего, нет. Христиане отвечают: Бог есть. Увидеть Его глазами нельзя, но на Него указывает многое вокруг нас. Скажем честно: доказать, что Бог есть, как задачу по математике, нельзя. Но и доказать, что Его нет, тоже нельзя. Можно только посмотреть, на что указывает мир вокруг. На что указывает мир У мира было начало — большинство учёных сегодня считают, что вселенная была не всегда: когда-то она появилась. А ничего не появляется само из ничего. Значит, кто-то её начал. Мир устроен очень точно — е","keys":"существует ли бог атеизм доказательства вера и разум сомнения"},{"title":"Что такое Библия?","url":"chto-takoe-bibliya.html","kind":"Урок 3","text":"Целая библиотека с одной общей историей. Библию знают все, хотя читали её немногие. Это самая издаваемая книга в мире. Что в ней такого? Христиане отвечают так: Библия — это книга, через которую говорит Бог. Её писали люди, но Бог вёл их. И через их слова Он рассказывает людям о Себе. У Библии много писателей, но, как верят христиане, один Автор. Целая библиотека Слово «Библия» значит «книги». И правда, под одной обложкой собраны 66 книг. Их написали около 40 человек: цари, пастухи, рыбаки, врач. Писали примерно 1500 лет. Там есть истории, песни, мудрые советы и письма. При этом у всех книг од","keys":"библия ветхий завет новый завет кто написал библию можно ли доверять связи между книгами переклички перекрёстные ссылки 40 авторов"},{"title":"Какой Бог?","url":"kakoy-bog.html","kind":"Урок 4","text":"Творец, святой, справедливый и любящий. Строгий старик на облаке? Безличная энергия? Добрый дедушка, который всё разрешает? Многие представляют Бога именно так. Христиане отвечают: Бог — Тот, Кто создал всё, и Он любит людей. С Ним можно говорить, как с живым. Он создал всё Бог был всегда, ещё до того, как появился мир. Всё, что есть, создал Он: звёзды, землю, жизнь и нас самих. Он знает всё и может всё. С Ним можно говорить Бог — не безличная сила. Он — личность: думает, чувствует, говорит. Энергии не скажешь «спасибо» и не расскажешь, что у тебя болит. А Богу можно. В Нём нет зла Библия называет Бога св","keys":"какой бог характер бога любовь бога справедливость святость троица"},{"title":"Зачем существует человек?","url":"zachem-chelovek.html","kind":"Урок 5","text":"Для чего мы живём и почему каждый человек ценен. «Зачем я живу?» Рано или поздно этот вопрос задаёт себе каждый. Христиане отвечают: человек создан, чтобы жить рядом с Богом и любить — Бога и людей. Мы похожи на Бога Библия говорит, что Бог создал человека по Своему образу. Это значит, что мы немного похожи на Него. Поэтому мы умеем любить, придумывать новое, отличать добро от зла. И поэтому ценен каждый человек: малыш, старик, больной. Не за ум, красоту или пользу, а просто потому, что он человек. Созданы для любви Однажды Иисуса спросили, что в жизни главное. Он ответил: Любить Бога всем сер","keys":"смысл жизни образ божий зачем человек ценность человека"},{"title":"Что такое грех?","url":"chto-takoe-greh.html","kind":"Урок 6","text":"Не только плохие поступки. Слово «грех» звучит старомодно. Но речь о том, что знакомо каждому. Христиане объясняют так: грех — это когда человек живёт по-своему, как будто Бога нет, и поступает против Его воли. Отсюда ложь, зависть, жестокость и всё зло в мире. Как это началось Библия рассказывает о первых людях, Адаме и Еве. Бог дал им всё и попросил только об одном: не есть плодов с одного дерева. Но змей обманул их. Он сказал, что Бог от них что-то скрывает. Библия называет этого змея дьяволом. Они поверили ему и решили, что сами знают лучше. С этого начался разрыв между людьми и Богом. Не только поступки Грех — это не только кража или убийство. Это и: Слов","keys":"грех что такое грех грехопадение адам и ева зло"},{"title":"Почему грех — это серьёзно?","url":"posledstviya-greha.html","kind":"Урок 7","text":"Что грех разрушает и почему хорошие дела не спасают. «Все не идеальны, что тут такого?» Так думают многие. Христиане отвечают: грех серьёзнее, чем кажется. Он ломает жизнь, и сами мы это не исправим. Что ломает грех Связь с Богом — грех встаёт между человеком и Богом, как стена. Отношения с людьми — ложь, предательство и зависть разрушают семьи и дружбу. Нас самих — сначала кажется, что это свобода. А потом человек не может остановиться. Библия говорит, что итог греха — смерть. Будет суд Библия говорит: каждый однажды ответит перед Богом за свою жизнь. Звучит страшно. Но подумайте: разве мы хо","keys":"последствия греха хороший человек почему бог не может просто простить суд смерть"},{"title":"Бог не отказался от человека","url":"obeshchanie.html","kind":"Урок 8","text":"Как Бог шаг за шагом готовил спасение. Люди отвернулись от Бога. Можно было бы ожидать, что и Бог отвернётся от них. Но Бог сделал наоборот. Он сразу пообещал, что спасёт людей. И потом много веков готовил это. Представьте родителей, у которых сын ушёл из дома. Они не перестают ждать. Держат дверь открытой и сами ищут способ его вернуть. Шаг за шагом Первое обещание — сразу после первого греха Бог сказал, что однажды зло будет побеждено. Авраам — Бог выбрал одного человека, Авраама, и пообещал: через твоих потомков добро придёт ко всем народам. Народ Израиля — из потомков Авраама вырос народ И","keys":"обещание авраам израиль моисей закон жертвы пророки мессия"},{"title":"Почему Иисуса называют Богом?","url":"iisus-syn-bozhiy.html","kind":"Урок 9","text":"Бог, Который стал человеком. В первом уроке мы видели: Иисус говорил и поступал так, как может только Бог. Христиане называют Его Сыном Божьим. Что это значит? Коротко: Иисус — и настоящий Бог, и настоящий человек одновременно. Что значит «Сын Божий» Это не значит, что у Бога родился ребёнок, как рождаются дети у людей. И не значит, что когда-то Сына не было. Он был всегда. Слово «Сын» говорит о другом. Сын человека — тоже человек. Так и Сын Бога — тоже Бог. Кому молился Иисус? Если Иисус — Бог, кому же Он молился? Вы, наверное, слышали слова «во имя Отца и Сына и Святого Духа». В них и есть о","keys":"сын божий бог ли иисус воплощение троица богочеловек"},{"title":"Почему Иисус умер на кресте?","url":"krest.html","kind":"Урок 10","text":"Зачем умер Иисус и что это меняет для нас. Крест был самой позорной казнью в Римской империи. Почему же христиане носят крест на груди? Потому что на кресте Иисус умер вместо нас. Он принял наказание, которое заслужили мы. Вспомним прошлые уроки Бог справедлив и не закрывает глаза на зло (урок 4). Все люди делали зло, и сами мы это не исправим (уроки 6 и 7). Пророки обещали Спасителя, Который пострадает за чужие грехи (урок 8). Иисус — и Бог, и человек (урок 9). Теперь всё сходится. Что произошло на кресте Иисус ни разу в жизни не сделал зла. Но на кресте Он взял на Себя наши грехи и наказание","keys":"крест распятие смерть иисуса жертва искупление примирение за грехи"},{"title":"Воскресение","url":"voskresenie.html","kind":"Урок 11","text":"Что случилось на третий день — и почему это меняет всё. После казни Иисуса ученики прятались за закрытыми дверями. А через несколько недель они открыто говорили на улицах того же Иерусалима: Он жив. Христиане уверены: Иисус действительно воскрес . Не в памяти учеников, а по-настоящему. Он умер и на третий день снова ожил. Что произошло Иисуса похоронили в пещере в скале и закрыли вход большим камнем. На третий день женщины пришли туда и нашли пещеру пустой. Потом Иисус много раз приходил к ученикам. Они говорили с Ним, касались Его, ели вместе с Ним. Однажды Его видели больше пятисот человек с","keys":"воскресение пасха пустая гробница воскрес ли иисус доказательства воскресения"},{"title":"Благодать","url":"blagodat.html","kind":"Урок 12","text":"Прощение нельзя заработать — его дарят. Всё в жизни приходится заслуживать: оценки, зарплату, уважение. Поэтому многие думают, что и с Богом так же: будь хорошим, и Он тебя примет. Христиане отвечают: нет. Прощение Бога нельзя заработать. Его можно только получить в подарок. Эту доброту Бога, которую нельзя заслужить, называют благодатью . Почему его нельзя заработать Хорошие дела не исправляют зла — если бы прощение надо было заработать, никто бы не справился. Всё уже оплачено — Иисус сделал всё нужное на кресте . Добавить к этому нечего, можно только принять. Представьте, что отец дарит маленькому сыну подарок, а сын протягивает е","keys":"благодать дар заслужить спасение по благодати добрые дела"},{"title":"Вера и покаяние","url":"vera-i-pokayanie.html","kind":"Урок 13","text":"Как принять Божий подарок. Подарок мало предложить — его нужно взять. Как принять прощение Бога? Иисус ответил коротко: Покайтесь и верьте. Иисус, Марка 1:15 Звучит непривычно, но смысл простой. Покаяться — значит повернуться к Богу. Верить — значит довериться Иисусу. Покаяться — развернуться Представьте, что вы едете и понимаете: еду не туда. Можно пожалеть об этом и ехать дальше. А можно развернуться. Покаяние — это такой разворот. Человек честно говорит Богу: я жил так, как будто Тебя нет, и делал зло. Без оправданий. И поворачивается к Богу. Покаяние не нужно, чтобы мучить себя. Оно нужно,","keys":"вера покаяние как стать христианином как спастись обращение молитва покаяния"},{"title":"Новая жизнь: что дальше","url":"chto-dalshe.html","kind":"Урок 14","text":"Первые шаги в жизни с Богом. Довериться Иисусу — это только начало. Как у новорождённого: жизнь уже есть, но расти ещё предстоит. Новая жизнь растёт постепенно. И растит её Сам Бог. Бог рядом Христиане верят, что Бог живёт в каждом, кто доверился Иисусу. Это Святой Дух . Он помогает понимать Бога и меняет человека изнутри: учит любить, прощать, терпеть. Что помогает расти Молитва — разговор с Богом своими словами, о чём угодно. Подробнее: «Как начать молиться?» Библия — понемногу, но регулярно. Лучше начать с Евангелия от Марка. Подробнее: «Как начать читать Библию?» Другие христиане — вера не","keys":"что дальше новая жизнь святой дух молитва церковь крещение библия"},{"title":"Можно ли доказать, что Бог существует?","url":"dokazat-boga.html","kind":"Вопрос","text":"Коротко Доказать Бога как теорему нельзя. Но и доказать, что Его нет, тоже нельзя. Зато есть серьёзные доводы, которые делают веру разумной. А главный довод для христиан — Иисус и Его воскресение . Чем довод отличается от доказательства Большинство важных вещей мы не можем доказать математически. Мы опираемся на доводы и выбираем самое разумное объяснение. С Богом так же. Вопрос не «кто докажет», а «какое объяснение лучше подходит к миру». Что говорит о Боге мир вокруг Начало вселенной — большинство учёных сегодня считают, что у вселенной было начало. Вместе с ней появились время, пространство и вещество. Значит, причина должна быть вне всего этого. Библия говорит то же ","keys":"доказать бога существует ли бог атеизм наука и вера большой взрыв мораль доказательства доказательство существования докажите докажи нет есть на самом деле реально атеист атеисты аргументы","pin":true,"short":"Доказать Бога как теорему нельзя. Но и доказать, что Его нет, тоже нельзя. Зато есть серьёзные доводы, которые делают веру разумной."},{"title":"Как начать читать Библию?","url":"kak-chitat-bibliyu.html","kind":"Вопрос","text":"Коротко Не начинайте с первой страницы. Откройте Евангелие от Марка. Читайте понемногу, когда есть время. Непонятно — нормально: записывайте вопросы. С чего начать Многие начинают с Бытия, застревают в законах книги Левит и бросают. Библию не обязательно читать подряд. Хороший порядок: Евангелие от Марка — самое короткое. Евангелие от Иоанна — глубже объясняет, Кто такой Иисус. Деяния апостолов — как появились первые христиане. Бытие (главы 1–12) и Псалмы . Какой перевод выбрать Синодальный перевод XIX века красивый, но местами трудный. Для начала удобнее современные переводы, они есть в бесплатных","keys":"как читать библию с чего начать перевод библии план чтения евангелие от марка первой какую книгу первой не понимаю трудно сложно понять откуда начинать","short":"Не начинайте с первой страницы. Откройте Евангелие от Марка. Читайте понемногу, когда есть время. Непонятно — нормально: записывайте вопросы."},{"title":"Как начать молиться?","url":"kak-molitsya.html","kind":"Вопрос","text":"Коротко Молитва — это разговор с Богом. Особые слова не нужны: говорите своими словами, как с тем, кто любит и слышит. Бог слышит каждого, даже если говорить совсем тихо или молча. Иисус дал образец — молитву «Отче наш». Особые слова не нужны Иисус предупреждал: не повторяйте слов механически, Бог и так знает, что вам нужно. Молиться можно вслух или про себя, дома или в метро. Можно коротко: «Боже, помоги». О чём говорить «Отче наш» показывает, о чём можно говорить с Богом: Обращаться как к Отцу — не как к чужому, а как к родному. Начинать с Бога — а не с моих нужд: да будет воля Твоя. Просить о простом — хлеб на сегодня. Просить прощения — и прощать других. Просить защиты — от зла. Не беспокойтесь ни о чём, а обо всём говорите Богу с благодарностью. Если не знаешь, что сказать Так бывает со всеми. Даже тогда Святой Дух помогает нам. Можно просто помолчать перед Богом. Или прочитать псалом как свою молитву. Если кажется, что Бог не отвечает Это знают многие верующие. В псалмах люди спрашивают Бога: сколько ещё ждать? почему Ты оставил меня? Иисус учил просить настойчиво. Но Бог отвечает по-разному: «да», «нет» или «подожди». Молитва — не способ управлять Богом, а способ быть с Ним.","keys":"молитва как молиться отче наш бог не отвечает слова молитвы слышит ли меня сбывается молчит правильно умею обращаться к богу разговаривать с богом говорить с богом для на молюсь а ничего для начинающих научиться","short":"Молитва — это разговор с Богом. Особые слова не нужны: говорите своими словами, как с тем, кто любит и слышит. Бог слышит каждого, даже если говорить совсем тихо или молча. Иисус дал образец — молитву «Отче наш»."},{"title":"Разве хорошего человека Бог не примет?","url":"khoroshiy-chelovek.html","kind":"Вопрос","text":"Коротко Бог принимает человека не за хорошие дела. Хороших людей много, но тех, кто ни разу не сделал зла, нет. А добрые дела не стирают плохие. Поэтому Бог прощает и принимает каждого, кто доверится Иисусу. Это подарок, его не нужно заслуживать. Хорошие по сравнению с кем? Добрых людей много и среди неверующих: совесть Бог дал каждому. На фоне преступников мы выглядим неплохо. Но Бог сравнивает нас не с соседом, а со Своим замыслом: любить Бога всем сердцем и ближнего, как себя. Иисус говорил, что гнев — уже шаг к убийству, а нечистый взгляд — уже измена. По такой мерке виноваты все. Почему добро не уравновешивает зло Божий суд — не весы: хорошие дела не перевешивают плохие. Опасность «хорошести» Притча Иисус рассказал о двух людях в храме. Уважаемый религиозный человек благодарил Бога, что он не такой, как другие. А презираемый сборщик налогов только просил: Боже, будь милостив ко мне, грешнику. Иисус сказал, что Бог простил второго. Иногда главная преграда к Богу — уверенность, что мне нечего прощать. Хорошая новость Вы спасены по благодати, через веру. Это не ваша заслуга, а Божий подарок. Не за дела, чтобы никто не хвалился. Апостол Павел, Ефесянам 2:8–9 Христос умер за нас, когда мы были ещё грешниками . Дверь открыта всем: и «хорошим», и тем, кто сделал много зла. Подробнее: урок «Вера и покаяние» . А хорошие дела важны. Но христианин делает добро не чтобы Бог его принял, а потому что Бог уже его принял.","keys":"хороший человек добрые дела рай спасение попаду ли я в никого не убивал без бога можно быть добрым веры атеисты мораль зачем вера если и так хорошим хорошим достаточно никому делаю зла делаю зла никому мешаю живу честно добрый мало хватит","short":"Бог принимает человека не за хорошие дела. Хороших людей много, но тех, кто ни разу не сделал зла, нет. А добрые дела не стирают плохие."},{"title":"Почему так много разных церквей?","url":"mnogo-tserkvey.html","kind":"Вопрос","text":"Коротко Христиане разделились из-за споров о том, как понимать веру и устраивать церковь . Три главные ветви — православие, католичество и протестантизм . Различия реальны. Но в главном большинство согласно: Бог — Отец, Сын и Святой Дух , а Иисус умер за нас и воскрес. Как возникло разделение 1054 год — западная церковь (центр в Риме) и восточная (центр в Константинополе) разделились. Главный спор был о власти: Рим считал, что Папа Римский стоит над всей церковью, а Восток с этим не согласился. Так появились католичество и православие. XVI век — Мартин Лютер и другие реформаторы настаивали: главный авторитет — только Библия, а спасение даётся по благодати через веру. Так появился протестантизм: лютеране, баптисты, пятидесятники, евангельские христиане и другие. На что опирается","keys":"церкви конфессии православие католичество протестантизм секты какая церковь правильная православные протестанты католики отличаются отличие разница православных протестантов католиков разделились раскол протестанты секта баптисты пятидесятники вера в какую ходить выбрать какую выбрать","short":"Христиане разделились из-за споров о том, как понимать веру и устраивать церковь . Три главные ветви — православие, католичество и протестантизм."},{"title":"Есть ли в Библии противоречия?","url":"protivorechiya.html","kind":"Вопрос","text":"Коротко Нет, настоящих противоречий в Библии нет. Есть места, которые на первый взгляд кажутся противоречиями. Но если посмотреть внимательнее, они объясняются контекстом, жанром или тем, что авторы смотрят на одно событие с разных сторон. И ни одно такое место не касается главного: кто такой Иисус и что Он сделал. Разные свидетели — разные детали Евангелия по-разному описывают утро воскресения : один автор упоминает одного ангела , другой двух. Так выглядят честные свидетельские показания. Если бы четыре рассказа совпадали слово в слово, это скорее говорило бы о сговоре. А в главном — гробница пуста, Иисус воскрес — все сходятся. Одно событие с разных сторон Матфей пишет, что Иуда повесился, а Деян","keys":"противоречия в библии ошибки в библии разные евангелия можно ли доверять библии ошибок противоречит сама себе нестыковки несоответствия неточности","short":"Нет, настоящих противоречий в Библии нет. Есть места, которые на первый взгляд кажутся противоречиями. Но если посмотреть внимательнее, они объясняются контекстом, жанром или тем, что авторы смотрят на одно событие с разных сторон."},{"title":"Почему существуют разные религии?","url":"raznye-religii.html","kind":"Вопрос","text":"Коротко Люди везде ищут Бога, и во многих религиях есть мудрость. Но на главные вопросы они отвечают по-разному, и все сразу правы быть не могут. Христианство отличается тем, что говорит не о том, как человек дотягивается до Бога, а о том, как Бог пришёл к человеку. Почему люди везде ищут Бога Библия говорит, что Бог вложил в сердце человека мысль о вечности. Бог создал людей, чтобы они искали Его, и Он недалеко от каждого. Поэтому христиане уважают искренний поиск и признают правду о совести и добре в других религиях. Ведут ли все религии к Богу? Говорят: это разные тропинки на одну гору. Но рели","keys":"религии все религии одинаковы ислам буддизм иудаизм единственный путь другие религии религия правильная какая религия правильная истинная религия бог один у всех об одном одно и то же мусульмане буддисты христианство и аллах лучше других религий почему именно христианство чем христианство лучше","short":"Люди везде ищут Бога, и во многих религиях есть мудрость. Но на главные вопросы они отвечают по-разному, и все сразу правы быть не могут."},{"title":"Почему Бог допускает страдания?","url":"stradaniya.html","kind":"Вопрос","text":"Коротко Библия отвечает так: Люди свободны — Бог создал нас свободными. Многое зло творят сами люди, когда выбирают зло. Мир сломан — когда люди отвернулись от Бога, сломалось всё творение. Отсюда болезни и катастрофы. Бог ещё ждёт — если бы Он убрал всё зло прямо сейчас, пришлось бы убрать и всех нас. Он даёт время, чтобы люди успели вернуться к Нему. Это не навсегда — Бог обещает, что однажды страданий больше не будет. Если вам сейчас очень тяжело Не оставайтесь с этим одни. Поговорите с близким человеком. Если есть мысли причинить себе вред, позвоните в службу экстренной психологической помощи вашей страны или по номеру 112. Откуда пришли страдания Бог создал мир без смерти и боли. В конце сотворения сказано: Бог посмотрел на всё, что создал, и увидел: всё очень хорошо. Бытие 1:31 Страдания пришли, когда первые люди выбрали жить без Бога. Библия называет это грехом . С тех пор сломан весь мир. Многое зло творят люди — Бог дал нам настоящую свободу, и люди часто выбирают зло. Болезни и катастрофы — не наказание конкретного человека, а знак того, что сломан весь мир. Иисус говорил: те, на кого упала башня, были не хуже других. Почему Бог не уберёт зло прямо сейчас Зло есть в каждом из нас. Если бы Бог уничтожил всё зло сегодня, Ему пришлось бы осудить и нас. Бог не опаздывает. Он терпит, потому что не хочет, чтобы кто-то погиб. 2 Петра 3:9 Можно спрашивать «почему?» В Библии многие кричат Богу от боли. Иов, потерявший всё, спорит с Богом и требует ответа. В псалме звучит: Боже мой, для чего Ты оставил меня? Бог не наказывает за такие вопросы. Бог хочет, чтобы трудные времена мы проходили не в одиночку, а вместе с Ним. С болью можно прийти к Нему прямо такой, какая она есть. Он не всегда сразу убирает беду, но обещает быть рядом и давать силы её пройти. В Библии Бог говорит: если пойдёшь через воду, Я буду с тобой, и реки тебя не потопят. Бог не стоит в стороне Он прошёл через боль — в Иисусе Бог Сам пережил голод, предательство, пытки и смерть. Он понимает нас изнутри. Он плачет вместе с нами — у могилы друга Лазаря Иисус плакал, хотя знал, что сейчас его воскресит. Он выводит добро из зла — казнь невиновного Сына Божьего Бог превратил в спасение мира. Бог может вывести добро даже из зла. Зло от этого не становится хорошим, но последнее слово не за ним. У страданий есть конец Бог обещает: Он отрёт каждую слезу, и не будет больше ни смерти, ни плача, ни боли. Воскресение Иисуса — залог, что это правда. Честно о границах Почему заболел именно этот ребёнок, почему именно сейчас — на это часто нет ответа. Вера не убирает вопросы, но даёт опору: Бог добр, Он рядом, и Он исправит то, что сломано.","keys":"страдания зло боль война болезнь почему бог допускает смерть близких несправедливость откуда есть создал дьявол свобода воли падение грехопадение в мире не уничтожит терпит чего ждёт остановит войну злых людей всемогущий прямо сейчас дети болеют болезни детей умирают хорошие люди умирают молодые плохо мне было плохо где был горе беда трагедия допустил помог несчастье за что мне это за что умерла мама умер папа умер близкий человек потерял близкого невинные страдают","pin":true,"short":"Короткой формулы, которая снимает боль, нет. Но Библия говорит три вещи. Страдания не были частью Божьего замысла. Бог не стоит в стороне: Он стал человеком, Иисусом, и Сам прошёл через боль и смерть."},{"title":"Существовал ли Иисус на самом деле?","url":"sushchestvoval-li-iisus.html","kind":"Вопрос","text":"Коротко Да. Историки, в том числе неверующие, не сомневаются, что Иисус — реальный человек. Он жил в Израиле в I веке и был казнён при Понтии Пилате. Спорят не о том, жил ли Он, а о том, кем Он был. Что признают историки Это не религиозная позиция, а научный консенсус. Историки согласны: Учитель из Галилеи — Иисус был иудейским учителем, и у Него были ученики. Казнён при Пилате — Его распяли в Иерусалиме по приговору Понтия Пилата. Весть о воскресении — вскоре Его последователи стали проповедовать, что Он воскрес. В советское время часто говорили, что Иисус — выдумка. Но наука от этой идеи давно отказалась. Кто писал о Нём, кроме христиан","keys":"исторический иисус существовал ли иисус тацит иосиф флавий миф реальный человек реально жил историческая фигура исторические доказательства иисуса выдуманный персонаж сказка придумали придумали иисуса","short":"Да. Историки, в том числе неверующие, не сомневаются, что Иисус — реальный человек. Он жил в Израиле в I веке и был казнён при Понтии Пилате."},{"title":"Кто создал Бога?","url":"kto-sozdal-boga.html","kind":"Вопрос","text":"Коротко Никто. У Бога нет начала: Он был всегда. Создать можно только то, что когда-то началось. А Бог не начинался. Почему вопрос звучит логично Мы привыкли: у всего есть причина. Дом построили строители, дерево выросло из семечка, человек родился у родителей. Поэтому кажется, что и у Бога должен быть Тот, Кто Его создал. Но правило звучит точнее так: причина есть у всего, что начинается . Дом когда-то начался, дерево тоже. А Бог, по вере христиан, не начинался никогда. Что-то должно существовать всегда В начале всей цепочки причин должно стоять что-то, что ни от чего не зависит и существует само по себе. Учёные говорят, что у В","keys":"кто создал бога откуда взялся бог начало бога вечность бесконечность причина вселенной появился сотворил до было всегда был","short":"Никто. У Бога нет начала: Он был всегда. Создать можно только то, что когда-то началось. А Бог не начинался. Почему вопрос звучит логично Мы привыкли: у всего есть причина."},{"title":"Как Бог может быть один и при этом Отец, Сын и Святой Дух?","url":"troitsa.html","kind":"Вопрос","text":"Коротко Бог один. Но Он существует как Отец, Сын и Святой Дух. Это не три бога и не один Бог в трёх масках. Христиане называют это Троицей . До конца понять это нельзя, но и придумать такое люди бы не стали. Откуда христиане это взяли Слова «Троица» в Библии нет. Но там есть три вещи, которые нужно соединить: Бог один — это главное убеждение Израиля, и Иисус его повторял. Каждый из Них — Бог — Отец — Бог, Иисус — Бог, Святой Дух — Бог. Библия говорит это о каждом. И Они разные — Отец говорит с Сыном, Сын молится Отцу, Отец и Сын посылают Духа. Первые христиане долго думали, как сказать об этом точно. Так появилось слово «Троица","keys":"троица отец сын святой дух три бога один бог как понять троицу триединый трех богов триединство и","short":"Бог один. Но Он существует как Отец, Сын и Святой Дух. Это не три бога и не один Бог в трёх масках. Христиане называют это Троицей ."},{"title":"Чему учил Иисус?","url":"chemu-uchil-iisus.html","kind":"Вопрос","text":"Коротко Иисус учил любить Бога всем сердцем и любить людей, как себя. Даже врагов. Он говорил, что Царство Божье уже пришло, и звал людей вернуться к Богу. А ещё Он много говорил о Себе: что пришёл от Бога и что через Него человек приходит к Богу. Две главные заповеди Однажды Иисуса спросили: какая заповедь в Законе главная? Он ответил: Люби Господа Бога всем сердцем, всей душой и всем разумом. И вторая похожа на неё: люби ближнего, как самого себя. Иисус, Матфея 22:37–39 Всё остальное, сказал Иисус, держится на этих двух. Слова, которые знают все Многие слова Иисуса стали частью нашей речи. Большинство из них прозвучало в Наг","keys":"чему учил иисус учение иисуса нагорная проповедь заповеди любите врагов не судите золотое правило говорил слова главное в учении притчи","short":"Иисус учил любить Бога всем сердцем и любить людей, как себя. Даже врагов. Он говорил, что Царство Божье уже пришло, и звал людей вернуться к Богу."},{"title":"Можно ли верить в чудеса Иисуса?","url":"chudesa.html","kind":"Вопрос","text":"Коротко Да. Христиане верят, что Иисус на самом деле исцелял больных, кормил толпы и воскрешал мёртвых. Если Бог создал мир и его законы, Он может и действовать в этом мире. А главное чудо — воскресение Иисуса. Разве наука не против чудес? Наука изучает, как мир работает обычно. Если бросить камень, он упадёт. Но наука не может доказать, что Тот, Кто создал мир, никогда не сделает что-то необычное. Чудо — это когда Бог, Который создал мир, делает то, что можем не мы, а только Он. Что говорят источники О чудесах Иисуса рассказывают все четыре Евангелия. Их записали в первые десятилетия после событий, когда ещё были живы свидетели. ","keys":"чудеса иисуса правда ли чудеса исцеления хождение по воде воскрешение лазаря наука чудо бывают выдумка ходил исцелял воскрешал мертвых превратил воду в вино","short":"Да. Христиане верят, что Иисус на самом деле исцелял больных, кормил толпы и воскрешал мёртвых. Если Бог создал мир и его законы, Он может и действовать в этом мире."},{"title":"Что на самом деле празднуют на Рождество и на Пасху?","url":"rozhdestvo-i-pasha.html","kind":"Вопрос","text":"Коротко На Рождество христиане празднуют, что Бог стал человеком: родился Иисус. На Пасху — что Иисус воскрес после смерти на кресте. Пасха — самый главный праздник христиан. Рождество Около двух тысяч лет назад в городке Вифлееме у девушки Марии родился Сын. Его положили в ясли — кормушку для скота, потому что в гостинице не было места. Пастухам ночью явились ангелы и сказали: сегодня родился Спаситель. Христиане верят, что этот ребёнок — Сам Бог, пришедший к людям. Поэтому Рождество — праздник о том, что Бог не остался далеко. Он пришёл к нам. Почему 25 декабря или 7 января Точной даты рождения Иисуса Библия не называет. Христиан","keys":"рождество пасха праздник что празднуют христос воскрес кулич яйца 25 декабря 7 января дата пасхи в разные дни разная красят крашеные куличи праздники христиан праздновать смысл смысл рождества","short":"На Рождество христиане празднуют, что Бог стал человеком: родился Иисус. На Пасху — что Иисус воскрес после смерти на кресте. Пасха — самый главный праздник христиан."},{"title":"Не изменили ли текст Библии за 2000 лет?","url":"ne-izmenili-li-bibliyu.html","kind":"Вопрос","text":"Коротко Нет. Текст Библии дошёл до нас очень точно. Сохранились тысячи древних рукописей, и их можно сравнить между собой. Различия между ними в основном мелкие: написание слов, порядок слов. Ни одно из них не меняет того, во что верят христиане. Тысячи рукописей Нового Завета на греческом языке сохранилось больше пяти тысяч рукописей и их отрывков. Самые ранние кусочки написаны всего через несколько десятков лет после оригиналов. Находка у Мёртвого моря В 1947 году пастух случайно нашёл в пещере у Мёртвого моря древние свитки. Среди них была почти целая книга пророка Исаии. Она оказалась на тысячу лет старше всех известных до это","keys":"изменили ли библию переписали библию искажение рукописи кумранские свитки переводы библии подлинность переписывали много раз церковники подделали доверять надежна оригинал подделка подделали фальшивка","short":"Нет. Текст Библии дошёл до нас очень точно. Сохранились тысячи древних рукописей, и их можно сравнить между собой. Различия между ними в основном мелкие: написание слов, порядок слов."},{"title":"Почему в Ветхом Завете Бог кажется жестоким?","url":"zhestokiy-bog.html","kind":"Вопрос","text":"Коротко Бог в Ветхом Завете тот же, что и в Новом: справедливый и милосердный. Некоторые места читать тяжело, и христиане этого не скрывают. Но если читать внимательно, видно: Бог наказывает поздно и после долгих предупреждений, а милует часто. Ветхий Завет полон милосердия Часто думают: в Ветхом Завете Бог злой, а в Новом добрый. Но сам Ветхий Завет описывает Бога так: Он любит людей, милосерден, долго терпит, полон доброты и всегда верен. Вспомните историю Ионы, которого проглотила огромная рыба. Бог послал Иону во вражеский город Ниневию. Жители раскаялись, и Бог их пощадил. Иона даже обиделся, что Бог такой добрый к врагам","keys":"жестокий бог ветхого завета потоп войны ханаан наказания бог гнев бог любовь трудные места библии убивал людей убивает злой жестокость ной истребил приказал убивать","short":"Бог в Ветхом Завете тот же, что и в Новом: справедливый и милосердный. Некоторые места читать тяжело, и христиане этого не скрывают."},{"title":"Что будет после смерти?","url":"posle-smerti.html","kind":"Вопрос","text":"Коротко Со смертью жизнь не заканчивается. Тело умирает, но человек продолжает жить и встречается с Богом. А в конце времён Бог воскресит всех людей. Те, кто доверился Иисусу, будут жить с Богом всегда. Смерть — не конец Библия говорит: человек — это не только тело. Когда тело умирает, сам человек не исчезает. Его душа продолжает жить. Иисус говорил разбойнику, который висел рядом с Ним на кресте и попросил о помощи: сегодня же будешь со Мной в раю. Не через тысячу лет, а сегодня. Это ещё не всё Христиане верят не просто в жизнь души где-то на небе. Бог обещал больше: в конце времён Он воскресит мёртвых. У людей снова будут тела, только новые, которые не болеют и не умирают. Рай — это не облака и арфы. Библия обещает обновлённый мир, где Бог будет жить с людьми и где не будет ни смерти, ни слёз, ни боли. Иисус воскрес первым и показал, как это будет. Поэтому для христиан Его воскресение — обещание и для них. Иисус сказал: Я — воскресение и жизнь; кто верит в Меня, оживёт, даже если умрёт. Иисус, Иоанна 11:25 Суд Библия говорит, что каждый человек встретится с Богом и даст отчёт о своей жизни. Об этом неприятно думать. Но это значит, что ничто не останется незамеченным: ни зло, ни добро. Для того, кто доверился Иисусу, этот суд не страшен. Его грехи уже прощены. Поэтому христианин может встречать смерть с надеждой. Чего в Библии нет В Библии нет: Переселения душ — человек живёт на земле один раз. Призраков — умершие не становятся призраками или ангелами . Зато есть твёрдое обещание: тот, кто с Богом, после смерти будет с Ним, а потом воскреснет.","keys":"что будет после смерти жизнь душа куда попадает рай ад воскресение мёртвых реинкарнация такое небеса царство небесное новая земля попаду ли я в кто попадёт вечная умирает человек умрем умру умер смерть есть небо увижу умерших близких встречу родных умершие родные умершие дети умерших детей младенцы загробная как выглядит ребенок умер где он сейчас мой ребенок умер на небе на небесах","short":"Со смертью жизнь не заканчивается. Тело умирает, но человек продолжает жить и встречается с Богом. А в конце времён Бог воскресит всех людей."},{"title":"Ад существует на самом деле?","url":"ad.html","kind":"Вопрос","text":"Коротко Да. Иисус говорил об аде чаще и серьёзнее, чем кто-либо в Библии. Ад — это жизнь вдали от Бога, а значит, вдали от всего доброго. Бог не хочет, чтобы туда попал хоть кто-то. Поэтому Он и пришёл спасти людей. Что такое ад Многие представляют ад как подвал, где черти жарят грешников на сковородках. Это из народных картинок, а не из Библии. Библия описывает ад образами огня и тьмы. Главный ужас ада в том, что там нет Бога. А Бог — источник всего хорошего: любви, радости, света, мира. Без Него не остаётся ничего хорошего. Как это сочетается с любовью Бог любит людей и поэтому не может быть равнодушен ко злу. Если бы суда не б","keys":"ад существует ли ад вечные муки геенна огненная как добрый бог может отправить в ад ада любящий отправляет справедливо мучения вечно мучиться навсегда выглядит огонь","short":"Да. Иисус говорил об аде чаще и серьёзнее, чем кто-либо в Библии. Ад — это жизнь вдали от Бога, а значит, вдали от всего доброго. Бог не хочет, чтобы туда попал хоть кто-то."},{"title":"Может ли Бог простить мне всё, что я сделал?","url":"prostit-vsyo.html","kind":"Вопрос","text":"Коротко Да. Нет такого греха, который Бог не может простить человеку, который приходит к Нему. Прощение зависит не от того, насколько тяжёл грех, а от того, что сделал Иисус. Кого простил Бог В Библии много людей, которые сделали страшные вещи и были прощены. Павел — преследовал христиан, бросал их в тюрьмы и одобрял казни. Потом он стал апостолом и написал почти половину книг Нового Завета. Пётр — трижды отрёкся от Иисуса в ночь ареста, пока не пропел петух. Иисус простил его и доверил ему заботу о Своих учениках. Матфей — собирал налоги для римлян и обманывал людей. Иисус позвал его за Собой. Матфей стал апостолом и написал Евангелие. Разбойник на кресте — ничего не успел исправить. Он только попросил Иисуса о милости и получил её. Это лишь несколько примеров. Бог простил и многих других. Иисус шёл к «плохим» Иисуса ругали за то, что Он ел за одним столом с обманщиками и людьми с дурной славой. От них все отворачивались, а Он сам шёл к ним. Иисус отвечал так: Я пришёл позвать не праведных, а грешников. Бог никого не прогоняет Того, кто приходит ко Мне, Я не прогоню. Иисус, Иоанна 6:37 Здесь нет условия «если ты достаточно хороший». Есть только одно: прийти. Чувство «я слишком плохой» не мешает прийти к Богу. Бог принимает как раз тех, кто знает, что сделал плохое. Бог не просто прощает. Он больше не вспоминает грехи того, кто пришёл к Нему. Я прощу их неправды и больше не вспомню их грехов. Евреям 8:12 Почему это возможно Иисус умер на кресте за грехи людей. Это значит, что за них уже заплачено. Если цена такая большая — жизнь Сына Божьего, — то её хватит на любой грех. Если мы признаём свои грехи, Бог, верный и справедливый, простит нам их и очистит нас от всякого зла. 1 Иоанна 1:9 А непростительный грех? Иисус однажды сказал, что есть грех, который не простится: хула на Святого Духа. Многие этого боятся. Но Иисус говорил о людях, которые упорно отвергали Бога и называли Его дело злом. Это не случайное слово и не один проступок. Это сознательное и окончательное «нет» Богу. Если вы боитесь, что совершили такой грех, это знак, что вы его не совершали. Тот, кто сказал Богу окончательное «нет», не переживает об этом. Прощение и последствия Бог прощает полностью. Но последствия поступков на земле могут остаться. Иногда нужно попросить прощения у людей, вернуть украденное или ответить по закону. Это не плата за Божье прощение, его не нужно отрабатывать. Это то, что делает человек, которого простили. Как прийти к Богу, рассказано в статье «Как начать отношения с Богом» .","keys":"простит ли бог всё прощение грехов непростительный грех хула на духа святого убийство аборт измена вина я слишком плохой меня не примет грешник много плохого сделал недостоин бога грешил ужасное сделала убил страшный совершил ужасный поступок","short":"Да. Нет такого греха, который Бог не может простить человеку, который приходит к Нему. Прощение зависит не от того, насколько тяжёл грех, а от того, что сделал Иисус."},{"title":"Зачем ходить в церковь, если можно верить дома?","url":"zachem-tserkov.html","kind":"Вопрос","text":"Коротко Верить можно и дома. Но Бог задумал христиан как семью, и в одиночку вера быстро слабеет. Церковь — это люди, которые вместе учатся, молятся и поддерживают друг друга. Церковь — это люди Слово «церковь» в Библии означает собрание людей, а не здание. Первые христиане собирались в обычных домах. Они вместе слушали учение апостолов, молились, ели и помогали тем, кто в нужде. Христиане и сейчас собираются: в больших храмах, в арендованных залах, в квартирах. Важно не место, а то, что люди собираются вокруг Иисуса. Одному трудно Одному трудно расти, задавать вопросы, держаться в тяжёлое время. Библия прямо советует не бросать","keys":"зачем ходить в церковь верить дома бог в душе церковь не нужна община богослужение обязательно без церкви без церкви у меня вера хожу","short":"Верить можно и дома. Но Бог задумал христиан как семью, и в одиночку вера быстро слабеет. Церковь — это люди, которые вместе учатся, молятся и поддерживают друг друга."},{"title":"Что такое крещение и зачем оно?","url":"kreshchenie.html","kind":"Вопрос","text":"Коротко Крещение — это когда человека погружают в воду или обливают водой. Это знак того, что он начинает новую жизнь с Иисусом. Иисус Сам велел крестить Своих учеников. Но церкви понимают крещение по-разному, и мы честно об этом говорим. Почему крестятся Перед тем как вернуться к Отцу, Иисус сказал ученикам: Идите ко всем народам, делайте людей Моими учениками и крестите их во имя Отца, Сына и Святого Духа. Иисус, Матфея 28:19 Иисус и Сам крестился в реке Иордан, хотя ни в чём не был виноват. Он показал пример. Что значит крещение В крещении сразу несколько смыслов: Омовение — как вода смывает грязь, так Бог очищает человека ","keys":"крещение зачем креститься крещение младенцев взрослое крещение погружение крестили в детстве покреститься крестился крещеный крестить ребенка как где обязательно второй раз перекреститься","short":"Крещение — это когда человека погружают в воду или обливают водой. Это знак того, что он начинает новую жизнь с Иисусом. Иисус Сам велел крестить Своих учеников."},{"title":"Что такое причастие?","url":"prichastie.html","kind":"Вопрос","text":"Коротко Причастие — это когда христиане вместе едят хлеб и пьют вино или виноградный сок в память о смерти Иисуса. Так велел Сам Иисус на последнем ужине с учениками. Тайная вечеря Многие видели картину Леонардо да Винчи «Тайная вечеря». На ней Иисус в последний вечер перед арестом ужинает с двенадцатью учениками. В тот вечер Иисус взял хлеб, поблагодарил Бога, разломил его и дал ученикам. Он сказал, что это Его тело, которое отдаётся за них. Потом дал им чашу вина и сказал, что это Его кровь, пролитая за многих. И сказал: делайте это в память обо ","keys":"причастие евхаристия вечеря господня тайная вечеря хлеб и вино тело и кровь христа причащаться причаститься причастится евхаристию","short":"Причастие — это когда христиане вместе едят хлеб и пьют вино или виноградный сок в память о смерти Иисуса. Так велел Сам Иисус на последнем ужине с учениками."},{"title":"Я сомневаюсь — это нормально для верующего?","url":"somneniya.html","kind":"Вопрос","text":"Коротко Да, это нормально. Сомневались даже ученики Иисуса, которые видели Его своими глазами. Сомнение — это не конец веры. Это вопросы, с которыми можно прийти к Богу. Фома неверующий Выражение «Фома неверующий» знают почти все. Фома был одним из двенадцати учеников Иисуса. Когда другие рассказали ему, что Иисус воскрес, он сказал: пока сам не увижу и не потрогаю раны, не поверю. Через неделю Иисус пришёл и предложил Фоме потрогать Его раны. Иисус не отругал его и не прогнал. Он ответил на его сомнение. А Фома воскликнул: Господь мой и Бог мой! Не только Фома Иоанн Креститель, который крестил Иисуса, сидя в тюрьме, послал","keys":"сомнения в вере сомневаюсь в боге нормально ли сомневаться фома неверующий потерял веру бывают потеряла не уверен что бог есть вдруг бога нет а если бога нет","short":"Да, это нормально. Сомневались даже ученики Иисуса, которые видели Его своими глазами. Сомнение — это не конец веры. Это вопросы, с которыми можно прийти к Богу."},{"title":"Наука и вера мешают друг другу?","url":"nauka-i-vera.html","kind":"Вопрос","text":"Коротко Нет. Наука и вера отвечают на разные вопросы. Наука объясняет, как устроен мир. Вера отвечает, почему он вообще есть и зачем мы живём. Многие великие учёные верили в Бога. Разные вопросы Наука и вера не спорят друг с другом, они просто отвечают на разные вопросы. Наука объясняет, как работает мир. Вера говорит о том, Кто его создал и зачем. Верующие учёные Многие основатели современной науки верили в Бога и видели в своей работе изучение Его мира. Исаак Ньютон — открыл закон всемирного тяготения и много писал о Библии. Блез Паскаль — великий математик и физик, автор глубоких размышлений о вере. Грегор Мендель — основате","keys":"наука и вера наука опровергла бога учёные верующие эволюция дарвин большой взрыв галилей сотворение мира доказала нет ученые верят в ученые сколько лет земле возраст земли динозавры обезьяны произошли от обезьяны теория эволюции произошел от обезьяны человек от обезьяны","short":"Нет. Наука и вера отвечают на разные вопросы. Наука объясняет, как устроен мир. Вера отвечает, почему он вообще есть и зачем мы живём."},{"title":"Почему христиане иногда поступают плохо?","url":"hristiane-plokho.html","kind":"Вопрос","text":"Коротко Потому что христиане тоже грешат. Христианин — это не человек, который стал лучше других. Это человек, который признал, что ему нужен Бог. Когда христиане делают зло, они поступают против учения Иисуса, а не по нему. Иисус предупреждал об этом Сильнее всего Иисус ругал не грешников, а лицемеров — религиозных людей, которые выглядели праведными , а внутри были злыми. Он говорил: Не каждый, кто говорит Мне «Господи, Господи», войдёт в Царство Небесное. Иисус, Матфея 7:21 Иисус знал, что среди тех, кто называет себя Его учениками, будут и плохие люди. Даже один из двенадцати, Иуда, предал Его. Крестовые походы и инк","keys":"христиане лицемеры плохие христиане крестовые походы инквизиция зло церкви почему верующие грешат церковь сделала столько зла лицемерие верующих обидели в обидели священники попы на мерседесах хуже неверующих","short":"Потому что христиане тоже грешат. Христианин — это не человек, который стал лучше других. Это человек, который признал, что ему нужен Бог."},{"title":"Во что мы верим","url":"beliefs.html","kind":"Статья","text":"Основа, на которой стоят все материалы сайта. Здесь коротко сказано, на чём стоят все материалы сайта. Мы христиане- протестанты и держимся евангельского понимания христианства. Главное Бог — Бог один, и Он создал всё. Бог — это Отец, Сын и Святой Дух : не три бога, а один Бог. Это называют Троицей . Библия — Библию писали люди, но через них говорил Бог. Поэтому для нас она — главная опора во всём, что касается веры и жизни. Человек — Бог создал человека похожим на Себя, чтобы мы жили с Ним. Но все люди отвернулись от Бога и делали зло. Это называют грехом , и он отделяет ","keys":"во что мы верим вероучение позиция конфессия евангельские христиане протестанты"},{"title":"Евангелие коротко","url":"gospel.html","kind":"Статья","text":"Главная весть христианства целиком, в пяти шагах. Слово « Евангелие » значит «добрая весть». Вот главное, во что верят христиане, в пяти шагах. Каждый шаг подробно разобран в уроках «Начать с нуля». 1. Бог создал нас, чтобы мы жили с Ним Мир не появился случайно. Его создал Бог. И людей Он создал, чтобы мы знали Его, говорили с Ним и жили рядом с Ним. Бог — не безличная сила. Он думает, говорит и любит. И хочет, чтобы мы любили Его и друг друга. 2. Мы отвернулись от Бога Люди решили жить так, как будто Бога нет, и сами решать, что хорошо, а что плохо. Библия называет это грехом . Так поступает","keys":"евангелие весть спасение крест кратко суть христианства","pin":true},{"title":"О чём страшно спросить","url":"trudno-sprosit.html","kind":"Подборка","text":"Вопросы О чём страшно спросить Честные ответы на то, что люди обычно держат в себе. «Сначала мне надо исправиться» Идти к Богу можно таким, какой есть. «Я боюсь, что Бог меня накажет» Строгий судья или отец, который ждёт. «Может ли Бог простить мне всё?» Есть ли грехи, которые Бог не прощает. «Как понять, что меня простили?» На чём держится уверенность в прощении. «Обещаю себе — и снова срываюсь» Почему так происходит и что с этим делать. «Почему Бог допускает страдания?» Откуда боль в мире и где в ней Бог. «Где сейчас тот, кто умер?» Что Библия говорит о жизни после смерти. «Что с детьми, которые умерли маленькими?» Христиане верят: они в руках доброго Бога. «Не могу простить того, кто сделал мне больно» Что значит простить и чего это не значит. Как начать молиться? Нужны ли особые слова и что делать, если Бог молчит. 1 мин «Мне не хочется жить» Вы не одни. Прочитайте это, пожалуйста. «Я сомневаюсь — мне к Богу нельзя?» Сомнения — честная часть пути. «Вера — это для слабых» Почему к Богу приходят и сильные люди. «Христианство — это сплошные запреты» Зачем Бог что-то запрещает. «Нужно много знать и прочитать всю Библию» Нет. Бог ждёт не знаний, а доверия. Хочется спросить лично? Напишите мне в Telegram Можно спросить о чём угодно, без осуждения.","keys":"страшно спросить страх боюсь примет ли меня бог простит ли бог стыдно неудобные вопросы","short":"Примет ли меня Бог? Почему Бог допускает страдания? Все такие вопросы в одном месте."},{"title":"Мифы о христианстве","url":"mify.html","kind":"Статья","text":"Семь частых мифов, которые многие слышали о христианстве. И что известно на самом деле. Про христианство многие что-то слышали со стороны: в школе, в интернете, от знакомых. Вот самые частые мифы и что о них известно на самом деле. 1. «Иисуса никогда не было» Нет, Иисус — реальный человек. Это признают историки, в том числе неверующие. Он жил в Израиле в I веке, и Его казнили при Понтии Пилате. О Нём писали не только христиане. Его упоминают римский историк Тацит и иудейский историк Иосиф Флавий. 2. «Библию много раз переписали, и смысл потерялся» Нет. Сохранились тысячи древних рукописей Библии. Их можно сравнить между собой и проверить, менялся ли текст. Различия между ними мелкие: как написано слово, в каком порядке стоят слова. Ни одно из них не меняет того, во что верят христиане. 3. «Воскресение придумали ученики» Вряд ли. После казни Иисуса ученики прятались от страха. А потом стали открыто говорить, что видели Его живым, и шли за это в тюрьму и на смерть. Человек может умереть за ошибку, в которую верит. Но за выдумку, которую сочинил сам, так не умирают. 4. «Наука доказала, что Бога нет» Нет. Наука изучает, как устроен мир. А есть ли у мира Создатель, наука ни доказать, ни опровергнуть не может. Многие великие учёные верили в Бога: Ньютон, Паскаль, Мендель. А Жорж Леметр, который первым предложил теорию Большого взрыва, был священником. 5. «Все религии говорят об одном и том же» Нет. Религии по-разному отвечают на главные вопросы: кто такой Бог, что не так с миром и как это исправить. Ответы часто противоположны, поэтому все сразу правы быть не могут. Христианство говорит, что Бог Сам пришёл к людям: Он стал человеком в Иисусе. 6. «Вера — это для слабых» Нет. Верить в Бога — значит честно признать, что ты не всё можешь сам. Это знают и сильные люди. Верующими были учёные Ньютон и Паскаль, писатель Достоевский, композитор Бах. А многие христиане шли за веру на смерть, и для этого нужна сила. 7. «Хожу в церковь — значит, я спасён» Нет. Бог смотрит на сердце. Можно ходить в церковь и при этом жить так, будто Бога нет. Бог прощает того, кто честно признал свои грехи, повернулся к Нему и доверился Иисусу. А церковь, Библия и молитва помогают такому человеку жить с Богом каждый день.","keys":"мифы иисуса не было существовал ли иисус библию переписали изменили библию воскресение выдумка наука доказала бога нет учёные все религии одинаковые вера для слабых хожу в церковь спасён спасение крещёный свечку ставлю обряды"},{"title":"Нужно ли сначала исправиться, чтобы прийти к Богу?","url":"snachala-ispravitsya.html","kind":"Вопрос","text":"Коротко Нет. К Богу приходят таким, какой ты есть сейчас. Бог сначала принимает человека, а потом помогает ему меняться. Врач нужен больным Иисус говорил: врач нужен не здоровым, а больным. Он пришёл к тем, у кого не получается жить правильно. Ждать, пока станешь лучше, не нужно. Притча Иисус рассказал о сыне, который ушёл из дома и растратил всё, что получил от отца. Когда у него ничего не осталось, он пошёл назад. Отец увидел его издалека, побежал навстречу и обнял. Сын ещё ничего не успел исправить. Так Иисус показал, как Бог встречает человека, который к Нему возвращается. Своими силами не получится Если ждать, когда станешь достаточно хорошим, можно ждать всю жизнь. Своими силами это не получается ни у кого. Меняться — уже вместе с Богом Перемены начинаются после того, как человек пришёл к Богу. И он меняется не один: Бог помогает. Это происходит постепенно. Срывы тоже бывают. Подробнее: «Почему я делаю плохое, даже когда не хочу?»","keys":"сначала надо исправиться стать лучше прийти к богу какой есть не готов измениться потом должен меняться меняться таким какая слишком плохой для бога брошу грешить приду","short":"Нет. К Богу приходят таким, какой ты есть сейчас. Бог сначала принимает человека, а потом помогает ему меняться."},{"title":"Бог меня накажет?","url":"bog-nakazhet.html","kind":"Вопрос","text":"Коротко Бог справедлив и не закрывает глаза на зло. Но Он не ищет, за что наказать. Он любит человека и хочет его простить. Наказание за наши грехи Иисус принял на Себя. Тому, кто доверился Иисусу, не нужно бояться Божьего наказания. Бог против зла, потому что любит Зло ранит людей, и Богу это не всё равно. Поэтому Он не делает вид, что зла нет. Библия честно говорит, что Бог будет судить. Но Божий гнев не похож на наш. Мы злимся, когда нас задели или когда мы устали. Божий гнев — это твёрдое «нет» злу, которое губит людей. Бог против зла, потому что любит нас. Бог ищет, а не ловит Притча Иисус рассказал о пастухе, у которого из ста овец потерялась одна. Пастух оставил остальных и искал, пока не нашёл. А потом нёс её домой на плечах и радовался. Так Иисус объяснил, как Бог относится к человеку, который от Него ушёл. Наказание уже понёс Иисус Бог не хочет наказывать. Он хочет, чтобы люди вернулись к Нему. Поэтому Иисус умер на кресте и принял на Себя наказание за наши грехи. Нет теперь никакого осуждения тем, кто во Христе Иисусе. Римлянам 8:1 Кто доверился Иисусу, тот больше не стоит перед Богом как обвиняемый. Беда — не всегда наказание Когда случается что-то плохое, легко подумать: это Бог меня наказывает. Иисус учил иначе. Как это было Ученики увидели человека, слепого от рождения, и спросили Иисуса: кто согрешил, он или его родители? Иисус ответил: ни он, ни родители. А потом исцелил его. Подробнее: «Почему Бог допускает страдания?»","keys":"бог накажет наказание божье боюсь бога строгий кара беда за грехи злится сердится наказывает гнев божий меня ненавидит на от мстит месть наказал","short":"Бог справедлив и не закрывает глаза на зло. Но Он не ищет, за что наказать. Он любит человека и хочет его простить. Наказание за наши грехи Иисус принял на Себя. Тому, кто доверился Иисусу, не нужно бояться Божьего наказания."},{"title":"Нужно ли много знать, чтобы прийти к Богу?","url":"nuzhno-mnogo-znat.html","kind":"Вопрос","text":"Коротко Нет. Прийти к Богу — не экзамен. Достаточно понять главное: кто такой Иисус и что Он сделал. Остальное узнают постепенно, всю жизнь. Первые ученики были простыми людьми Первые ученики Иисуса были рыбаками. Иисус не сказал им: сначала выучите. Он сказал: идите за Мной. Учились они уже рядом с Ним. Как это было Рядом с Иисусом распяли разбойника. Он почти ничего не знал о Боге и уже ничего не успевал выучить. Он только попросил: вспомни меня. Иисус ответил: сегодня же будешь со Мной в раю. Подробнее: «Можно ли прийти к Богу перед самой смертью?» С чего начать Узнать главное — вся суть христианства в пяти шагах: «Евангелие коротко» . Поговорить с Богом — своими словами, как получится. Особых слов не нужно. Читать понемногу — Библию лучше начинать с Евангелия, там рассказ об Иисусе.","keys":"нужно много знать прочитать всю библию мало знаю не разбираюсь с чего начать экзамен ничего о боге ничего читать обязательно","short":"Нет. Прийти к Богу — не экзамен. Достаточно понять главное: кто такой Иисус и что Он сделал. Остальное узнают постепенно, всю жизнь."},{"title":"Как начать отношения с Богом","url":"otklik.html","kind":"Статья","text":"Если вы хотите ответить Богу: что это значит, с чего начать и что будет дальше. Если вы прочитали о Евангелии и почувствовали, что это касается и вас, вот коротко, что значит ответить Богу. Что значит ответить Иисус сказал: покайтесь и верьте. Покаяться — развернуться: честно признать перед Богом, что жил без Него, и повернуться к Нему. Поверить — довериться Иисусу: тому, что Он умер за ваши грехи и воскрес. Прощение — подарок. Его не нужно заслуживать. Подробнее: урок «Вера и покаяние» . Как это сделать Особых слов и обрядов нет: Бог смотрит на сердце. Можно просто поговорить с Ним своими словами, вслух или про себя","keys":"как стать христианином как поверить обратиться к богу принять иисуса покаяние молитва в бога хочу хочу верить прийти начать верить уверовать","pin":true},{"title":"Бог","url":"topic-god.html","kind":"Тема","text":"Существует ли Бог, какой Он и почему в мире есть страдания"},{"title":"Иисус Христос","url":"topic-jesus.html","kind":"Тема","text":"Кем Он был, что говорил о Себе, Его смерть и воскресение"},{"title":"Библия","url":"topic-bible.html","kind":"Тема","text":"Как она появилась, можно ли ей доверять и как её читать"},{"title":"Человек и грех","url":"topic-human.html","kind":"Тема","text":"Зачем мы созданы, что такое грех и откуда зло"},{"title":"Спасение","url":"topic-salvation.html","kind":"Тема","text":"Крест, благодать, прощение, вера и покаяние"},{"title":"Жизнь с Богом","url":"topic-life.html","kind":"Тема","text":"Молитва, Библия, Святой Дух и церковь"},{"title":"Христианство и мир","url":"topic-world.html","kind":"Тема","text":"Другие религии и почему так много разных церквей"},{"title":"Ангел","url":"glossary.html#angel","kind":"Словарь","text":"Слово значит «вестник». Ангелы — духовные существа, которых создал Бог. Они служат Ему и иногда передают людям Его слова. Умершие люди ангелами не становятся.","keys":"ангел ангелы ангелов ангела ангелам"},{"title":"Апостол","url":"glossary.html#apostol","kind":"Словарь","text":"Буквально «посланник». Так называют двенадцать ближайших учеников Иисуса, которых Он послал рассказывать о Нём, а также Павла. Их письма вошли в Новый Завет.","keys":"апостол апостолы апостолов апостола апостолам"},{"title":"Библия","url":"glossary.html#bibliya","kind":"Словарь","text":"Собрание из 66 книг, которые писали разные люди на протяжении примерно полутора тысяч лет. Христиане верят, что через эти книги говорит Бог. Делится на Ветхий и Новый Завет.","keys":"библия библии библию библией"},{"title":"Благодать","url":"glossary.html#blagodat","kind":"Словарь","text":"Доброта Бога, которую человек не заслужил и не может заслужить. Прощение и новая жизнь с Богом даются по благодати, то есть как подарок, а не как награда за хорошие дела.","keys":"благодать благодати благодатью"},{"title":"Вера","url":"glossary.html#vera","kind":"Словарь","text":"В Библии вера — это не просто согласие с тем, что Бог существует, а доверие Ему. Верить в Иисуса значит полагаться на Него: на то, Кто Он и что Он сделал.","keys":"вера веры веру верой"},{"title":"Ветхий Завет","url":"glossary.html#vethiy-zavet","kind":"Словарь","text":"Первая, большая часть Библии. Книги, написанные до рождения Иисуса: о сотворении мира, истории народа Израиля, законы, молитвы и пророчества. «Завет» значит «договор, союз».","keys":"ветхий завет ветхого завета ветхом завете"},{"title":"Вечная жизнь","url":"glossary.html#vechnaya-zhizn","kind":"Словарь","text":"Не просто жизнь, которая длится бесконечно, а жизнь с Богом. По словам Иисуса, она начинается уже сейчас, когда человек узнаёт Бога, и продолжается после смерти.","keys":"вечная жизнь вечной жизни вечную жизнь"},{"title":"Воскресение","url":"glossary.html#voskresenie","kind":"Словарь","text":"Возвращение к жизни после смерти. Христиане верят, что Иисус на третий день после казни воскрес телесно, а не только «в памяти учеников». И что однажды воскреснут все люди.","keys":"воскресение воскресения воскресении воскрес воскресил воскреснут"},{"title":"Грех","url":"glossary.html#greh","kind":"Словарь","text":"Всё, чем человек нарушает волю Бога: поступки, слова, мысли и желания, а также доброе, которое он знал, что нужно сделать, но не сделал. В основе греха — отворачивание от Бога, желание жить так, будто Бог не нужен.","keys":"грех греха грехи грехов грехом грехам грехах грешник грешники грешниками"},{"title":"Евангелие","url":"glossary.html#evangelie","kind":"Словарь","text":"В переводе с греческого «добрая весть»: весть о том, что Бог через Иисуса Христа открыл людям путь к прощению и примирению с Собой. Евангелиями также называют четыре книги о жизни Иисуса: от Матфея, Марка, Луки и Иоанна.","keys":"евангелие евангелия евангелии евангелий"},{"title":"Евангельские христиане","url":"glossary.html#evangelskie-hristiane","kind":"Словарь","text":"Так называют протестантов, для которых главное — личная вера в Иисуса, Библия как высший авторитет и рассказ другим о Евангелии. Это широкое движение: в него входят баптисты, пятидесятники и многие другие церкви. Авторы этого сайта — евангельские христиане.","keys":"евангельские христиане евангельский евангельское понимание евангелисты баптисты пятидесятники"},{"title":"Жертва","url":"glossary.html#zhertva","kind":"Словарь","text":"В Ветхом Завете люди приносили Богу в жертву животных. Это показывало: грех ведёт к смерти, но Бог может принять другую жизнь вместо жизни человека. Христиане верят, что Иисус стал последней жертвой. Он отдал Свою жизнь за людей, и больше жертвы не нужны.","keys":"жертва жертвы жертвоприношение агнец"},{"title":"Завет","url":"glossary.html#zavet","kind":"Словарь","text":"Союз, договор между Богом и людьми, в котором Бог даёт обещания. Отсюда названия двух частей Библии: Ветхий (старый) и Новый Завет.","keys":"завет завета заветы"},{"title":"Закон","url":"glossary.html#zakon","kind":"Словарь","text":"Так в Библии часто называют правила и заповеди, которые Бог дал народу Израиля через Моисея. Например, Десять заповедей. Ещё так называют первые пять книг Библии.","keys":"закон закон моисея тора десять заповедей"},{"title":"Заповедь","url":"glossary.html#zapoved","kind":"Словарь","text":"Указание Бога о том, как жить. Самые известные — десять заповедей. Иисус сказал, что главные заповеди — любить Бога всем сердцем и любить ближнего, как самого себя.","keys":"заповедь заповеди заповедей заповедям"},{"title":"Израиль","url":"glossary.html#izrail","kind":"Словарь","text":"Народ, который произошёл от Авраама и с которым Бог заключил завет. Большая часть Ветхого Завета — история этого народа. Иисус по рождению был израильтянином, иудеем.","keys":"израиль израиля израилю израильтяне"},{"title":"Искупление","url":"glossary.html#iskuplenie","kind":"Словарь","text":"Освобождение за выкуп. В Библии так описывают то, что сделал Иисус: Своей смертью Он освободил людей от власти греха и его последствий.","keys":"искупление искупления искупил"},{"title":"Крест","url":"glossary.html#krest","kind":"Словарь","text":"Орудие казни в Римской империи, самой мучительной и позорной. На кресте был казнён Иисус. Для христиан крест стал знаком того, что Иисус умер за людей.","keys":"крест креста кресте крестом"},{"title":"Крещение","url":"glossary.html#kreschenie","kind":"Словарь","text":"Погружение в воду (или обливание водой) как знак того, что человек начинает новую жизнь с Иисусом. Иисус поручил Своим ученикам крестить тех, кто станет Его учениками. Христианские церкви по-разному понимают смысл крещения.","keys":"крещение крещения крестить крестились"},{"title":"Мессия","url":"glossary.html#messiya","kind":"Словарь","text":"Обещанный Богом Спаситель и Царь, которого ждал народ Израиля. Слово еврейское, по-гречески оно звучит как «Христос». Значит «помазанник».","keys":"мессия мессии мессию христос христа христе"},{"title":"Молитва","url":"glossary.html#molitva","kind":"Словарь","text":"Разговор с Богом. Можно говорить своими словами, о чём угодно: благодарить, просить, признаваться, спрашивать. Особые слова или место не обязательны.","keys":"молитва молитвы молитву молиться молился"},{"title":"Нагорная проповедь","url":"glossary.html#nagornaya-propoved","kind":"Словарь","text":"Самая известная речь Иисуса. Он произнёс её на склоне горы перед учениками и толпой. В ней прозвучали молитва «Отче наш» и слова «Не судите, и не будете судимы». Её записал Матфей в своём Евангелии.","keys":"нагорная проповедь заповеди блаженства отче наш не судите"},{"title":"Новый Завет","url":"glossary.html#novyy-zavet","kind":"Словарь","text":"Вторая часть Библии: книги, написанные после жизни Иисуса. Четыре Евангелия о Его жизни, история первых христиан и письма апостолов.","keys":"новый завет нового завета новом завете"},{"title":"Покаяние","url":"glossary.html#pokayanie","kind":"Словарь","text":"Разворот жизни. Человек признаёт перед Богом, что был неправ, и поворачивается к Нему. Это не только сожаление, но и решение изменить направление.","keys":"покаяние покаяния покаяться покайтесь кается"},{"title":"Праведность","url":"glossary.html#pravednost","kind":"Словарь","text":"Быть правым перед Богом, жить так, как Он задумал. Своими силами праведным перед Богом не становится никто. Христиане верят, что Бог дарит праведность тем, кто доверился Иисусу: прощает их и принимает как Своих.","keys":"праведность праведный праведные праведник"},{"title":"Предание","url":"glossary.html#predanie","kind":"Словарь","text":"Учение церкви, которое передаётся из поколения в поколение: решения древних церковных соборов, труды первых христианских учителей, обычаи. Православные и католики считают Предание важным наравне с Библией. Протестанты уважают его, но проверяют всё по Библии.","keys":"предание священное предание традиция церкви"},{"title":"Примирение","url":"glossary.html#primirenie","kind":"Словарь","text":"Восстановление разрушенных отношений. В Библии так говорится о том, что через Иисуса Бог восстановил отношения людей с Собой.","keys":"примирение примирения примирил примириться примирением"},{"title":"Причастие","url":"glossary.html#prichastie","kind":"Словарь","text":"Хлеб и вино (или виноградный сок), которые христиане вместе едят и пьют в память о смерти Иисуса. Так велел Сам Иисус на последнем ужине с учениками. Ещё его называют евхаристией и вечерей Господней.","keys":"причастие евхаристия вечеря господня хлебопреломление тайная вечеря"},{"title":"Пророк","url":"glossary.html#prorok","kind":"Словарь","text":"Человек, через которого Бог говорил к людям. Пророки призывали вернуться к Богу, а иногда говорили о будущем. Их книги составляют большую часть Ветхого Завета.","keys":"пророк пророка пророки пророков пророчество пророчества"},{"title":"Протестанты","url":"glossary.html#protestanty","kind":"Словарь","text":"Одна из трёх главных ветвей христианства, вместе с православными и католиками. Появилась в XVI веке. Для протестантов главный авторитет — только Библия, а спасение — подарок, который принимают верой. К протестантам относятся лютеране, баптисты, пятидесятники, евангельские христиане и другие.","keys":"протестанты протестантизм протестант лютеране баптисты"},{"title":"Прощение","url":"glossary.html#proschenie","kind":"Словарь","text":"Решение не взыскивать с человека за то, что он сделал плохого. Бог прощает тех, кто доверяется Иисусу: вина снимается, и отношения восстанавливаются.","keys":"прощение прощения простить прощает"},{"title":"Псалмы","url":"glossary.html#psalmy","kind":"Словарь","text":"Книга молитв и песен в Ветхом Завете. В ней 150 псалмов, многие написал царь Давид. В псалмах люди благодарят Бога, радуются, просят о помощи и даже жалуются Ему.","keys":"псалмы псалом псалтирь давид"},{"title":"Реформация","url":"glossary.html#reformatsiya","kind":"Словарь","text":"Движение в XVI веке, когда Мартин Лютер и другие стали призывать церковь вернуться к Библии. Они учили, что главный авторитет — Библия, а спасение даётся по благодати через веру. Так появились протестантские церкви.","keys":"реформация реформаторы лютер мартин лютер"},{"title":"Святой Дух","url":"glossary.html#svyatoy-duh","kind":"Словарь","text":"Бог, Который действует в мире и в людях. Христиане верят, что Святой Дух живёт в каждом, кто доверился Иисусу: помогает понимать Бога, меняться и жить по-новому. Одно из Лиц Троицы.","keys":"святой дух святого духа святым духом святом духе"},{"title":"Святость","url":"glossary.html#svyatost","kind":"Словарь","text":"Особая чистота и инаковость Бога: в Нём нет никакого зла, и Он отличается от всего, что Он создал. Свят — значит совершенно чист и «отделён» от зла.","keys":"святость свят святой святости"},{"title":"Священное Писание","url":"glossary.html#svyashchennoe-pisanie","kind":"Словарь","text":"Другое название Библии. Так говорят, чтобы подчеркнуть: это особая книга, через неё говорит Бог. Во времена Иисуса Писанием называли книги Ветхого Завета.","keys":"священное писание писание писания"},{"title":"Символ веры","url":"glossary.html#simvol-very","kind":"Словарь","text":"Короткий текст, где перечислено главное, во что верят христиане: о Боге Отце, Сыне и Святом Духе, о смерти и воскресении Иисуса. Самый известный — Никейский символ веры, его приняли в IV веке. С ним согласны православные, католики и большинство протестантов.","keys":"символ веры никейский символ веры кредо"},{"title":"Спасение","url":"glossary.html#spasenie","kind":"Словарь","text":"Избавление от греха и его последствий и восстановление отношений с Богом. Христиане верят, что спасение даёт Бог через Иисуса, а человек принимает его верой.","keys":"спасение спасения спасти спасён спасены спасает спаситель спасителя"},{"title":"Суд","url":"glossary.html#sud","kind":"Словарь","text":"Христиане верят, что Бог справедлив и что однажды каждый человек даст Ему отчёт за свою жизнь. Бог не делает вид, что зла нет.","keys":"суд суда судом"},{"title":"Сын Божий","url":"glossary.html#syn-bozhiy","kind":"Словарь","text":"Так в Библии называют Иисуса. Это не значит, что Бог «родил» Его, как рождаются люди, или что Он младше Отца. Сын существует всегда, вместе с Отцом. Слово «Сын» говорит о самой близкой связи и о том, что Он одной природы с Богом Отцом.","keys":"сын божий сына божьего сыном божьим сына сын"},{"title":"Троица","url":"glossary.html#troitsa","kind":"Словарь","text":"Христиане верят в одного Бога, Который существует как Отец, Сын и Святой Дух. Это не три бога и не три «маски» одного, а один Бог в трёх Лицах. Само слово «Троица» в Библии не встречается, но христиане используют его, чтобы обобщить то, что Библия говорит о Боге.","keys":"троица троицы троицу троицей троице"},{"title":"Христос","url":"glossary.html#hristos","kind":"Словарь","text":"Это не фамилия Иисуса. Это Его звание. По-гречески «Христос» значит «Помазанник», то же, что еврейское слово «Мессия». Так называли Спасителя, Которого обещал Бог. «Иисус Христос» значит «Иисус — Мессия».","keys":"христос христа помазанник мессия иисус христос"},{"title":"Царство Божье","url":"glossary.html#tsarstvo-bozhe","kind":"Словарь","text":"Главная тема проповеди Иисуса. Это не страна на карте, а власть Бога: там, где Бога признают Царём, где Его воля исполняется. Царство уже началось с приходом Иисуса и полностью наступит в будущем.","keys":"царство божье царства божьего царстве божьем царство"},{"title":"Церковь","url":"glossary.html#tserkov","kind":"Словарь","text":"Прежде всего не здание, а люди: все, кто верит в Иисуса. А также конкретная община христиан, которые собираются вместе, чтобы молиться, читать Библию и поддерживать друг друга.","keys":"церковь церкви церковью церквей"},{"title":"Почему Бога не видно?","url":"pochemu-boga-ne-vidno.html","kind":"Вопрос","text":"Коротко Бог — не предмет нашего мира, поэтому Его нельзя увидеть глазами, как дерево или человека. Но Он не прячется: христиане верят, что Бог Сам пришёл к людям и стал человеком — Иисусом. Бог не часть мира Бог создал мир, но не стоит в нём как ещё одна вещь. Поэтому Бога не найти в телескоп. Бог Сам пришёл к людям Христиане верят, что две тысячи лет назад Бог пришёл к людям как человек. Ученики Иисуса видели Его, слышали и трогали руками. Один из учеников попросил: покажи нам Бога. Иисус ответил: Кто видел Меня, видел и Отца. Иисус, Иоанна 14:9 Почему не показаться всем сразу Если бы Бог явился во всей силе, никто не смог бы с Ним спорить. Но Бог хочет не покорности от страха, а доверия и любви. Любовь силой не получишь. Многие видели чудеса Иисуса и всё равно не поверили. Значит, дело не только в том, чтобы увидеть. Как Бога узнают сегодня Бога узнают: Через Библию — в ней Бог рассказывает о Себе. Через м","keys":"почему бога не видно невидимый бог покажись бог прячется увидеть бога где бог докажи что ты есть покажется показывается скрывается являет себя","short":"Бог — не предмет нашего мира, поэтому Его нельзя увидеть глазами, как дерево или человека. Но Он не прячется: христиане верят, что Бог Сам пришёл к людям и стал человеком — Иисусом."},{"title":"Бог мужчина или женщина?","url":"bog-muzhchina.html","kind":"Вопрос","text":"Коротко Ни то, ни другое. Бог — не человек, у Него нет тела и пола. Библия называет Его Отцом не потому, что Он мужчина, а чтобы показать, как Он относится к нам. У Бога нет тела Мужчина и женщина — это то, какими Бог создал людей. Сам Бог — Творец, а не часть творения. Библия говорит, что Бог есть Дух. Бог создал человека по Своему образу — и мужчину, и женщину. Значит, оба одинаково отражают что-то от Бога. Почему тогда «Отец» Так Бога называл Иисус, и так Он научил молиться: «Отче наш». Слово «Отец» говорит о заботе, защите и близости. Бог не далёкая сила, а Тот, Кто любит, как родитель. Христиане говорят о Боге «Он» по примеру Библии. Это не значит, что женщины Богу дальше или дороже Ему меньше. В Библии есть и образы матери Как мать — Бог говорит, что утешит людей, как мать утешает ребёнка. Как птица — Иисус сравнил Себя с птицей, которая собирает птенцов под крылья. Все эти образы ","keys":"бог мужчина или женщина пол бога бог отец почему он богиня мать женщины она называют отцом мужского рода","short":"Ни то, ни другое. Бог — не человек, у Него нет тела и пола. Библия называет Его Отцом не потому, что Он мужчина, а чтобы показать, как Он относится к нам."},{"title":"Зачем Бог создал мир?","url":"zachem-sozdal-mir.html","kind":"Вопрос","text":"Коротко Не потому, что Ему чего-то не хватало. Богу не было ни одиноко, ни скучно. Он создал мир из любви: чтобы поделиться жизнью и радостью. Богу ничего не нужно Иногда думают: Бог создал людей, потому что Ему было одиноко. Но христиане верят, что в Боге всегда была любовь. Отец, Сын и Святой Дух любили друг друга ещё до сотворения мира. Значит, мир — не способ заполнить пустоту. Мир как подарок Бог создал мир, чтобы подарить жизнь и любить. В начале Библии Бог смотрит на всё, что создал, и видит: всё очень хорошо. А зачем человек Человек создан, чтобы знать Бога, любить Его и заботиться о мире. Это не тяжёлая обязанность, а то, для чего мы устроены. Человек по-настоящему живёт рядом с Богом.","keys":"зачем бог создал мир зачем бог создал людей зачем мы богу смысл творения богу было скучно одиноко живем жизни в чем жить для чего живем нужен человек для чего созданы","short":"Не потому, что Ему чего-то не хватало. Богу не было ни одиноко, ни скучно. Он создал мир из любви: чтобы поделиться жизнью и радостью."},{"title":"Если Бог всё знает заранее, есть ли у меня свобода?","url":"svoboda-i-sudba.html","kind":"Вопрос","text":"Коротко Да, свобода есть. Бог знает будущее, но это не значит, что Он нас заставляет. Наши решения настоящие, и мы за них отвечаем. Знать — не значит заставлять Бог видит всю нашу жизнь сразу. Но от этого наш выбор не становится ненастоящим. Библия говорит о двух вещах сразу Бог управляет историей — ничто не выходит из-под Его власти. И человек выбирает — Бог снова и снова зовёт людей: выберите жизнь, вернитесь ко Мне. Как именно одно сочетается с другим, мы до конца не понимаем. Христиане разных церквей объясняют это по-разному. Но все согласны: Бог не играет людьми, как куклами. Слепой судьбы нет Христианство не верит в рок, который всё решил за нас. За миром стоит не безличная судьба, а Бог, Который нас любит. Поэтому можно спокойно принимать решения и молиться о них. А ошибки не ставят крест на жизни: Бог умеет исправлять и их.","keys":"судьба предопределение свобода воли бог всё знает заранее рок всё решено за нас предначертано фатум предрешено все предрешено есть ли будущее все все в руках бога","short":"Да, свобода есть. Бог знает будущее, но это не значит, что Он нас заставляет. Наши решения настоящие, и мы за них отвечаем."},{"title":"Как выглядел Иисус?","url":"kak-vyglyadel.html","kind":"Вопрос","text":"Коротко Точно мы не знаем: Евангелия не описывают Его внешность. Скорее всего, Он был похож на обычного еврея своего времени: смуглый, темноволосый, с руками рабочего человека. Евангелия об этом молчат Авторы Евангелий подробно пишут, что Иисус говорил и делал, но не пишут, какого Он был роста и какого цвета у Него глаза. Им было важнее, Кто Он. Почему картины такие разные Художники разных стран рисовали Иисуса похожим на своих. В Европе Он светлый, в Эфиопии темнокожий, в Китае — с восточными чертами. Знаменитые картины и иконы — это не портреты. Это попытка показать, Кем Иисус был для людей. А Туринская плащаница? Некоторые считают, что на этой древней ткани отпечаталось тело Иисуса. Учёные спорят о ней до сих пор. Христианская вера от этого спора не зависит. Что важнее внешности Задолго до Иисуса пророк писал, что в Нём не будет ничего броского. Люди шли к Нему не за красотой, а потом","keys":"как выглядел иисус внешность иисуса лицо иисуса портрет плащаница туринская цвет кожи иисуса белым белый был какого цвета кожа волосы глаза рост христос евреем еврей","short":"Точно мы не знаем: Евангелия не описывают Его внешность. Скорее всего, Он был похож на обычного еврея своего времени: смуглый, темноволосый, с руками рабочего человека."},{"title":"Правда ли Иисус родился от девы?","url":"devstvennoe-rozhdenie.html","kind":"Вопрос","text":"Коротко Да, христиане верят, что Мария родила Иисуса, не зная мужа. Это чудо. Так Бог показал, что Иисус — не просто ещё один человек, а Сын Божий, пришедший в мир. Что рассказывают Евангелия Два Евангелия, от Матфея и от Луки, рассказывают об этом. Ангел пришёл к молодой девушке Марии и сказал, что она родит Сына от Святого Духа. Мария удивилась: как это будет, если у меня нет мужа? Её жених Иосиф сначала хотел тихо расторгнуть помолвку. Ему тоже пришлось поверить. В это трудно поверить — и тогда было трудно Люди древности прекрасно знали, откуда берутся дети. Поэтому Иосиф и встревожился. Евангелисты понимали, насколько это необычно. Но если Бог создал саму жизнь, Ему не трудно начать одну жизнь по-особому. Зачем это Иисус — не человек, который со временем стал Богом. Бог Сам пришёл в мир и стал человеком. Необычное рождение — знак этого. Иногда это путают с «непорочным зачатием». У ка","keys":"непорочное зачатие родился от девы дева мария рождение иисуса как мария родила без мужа девственное рождение отец кто отец иосиф","short":"Да, христиане верят, что Мария родила Иисуса, не зная мужа. Это чудо. Так Бог показал, что Иисус — не просто ещё один человек, а Сын Божий, пришедший в мир."},{"title":"Может, воскресение Иисуса — выдумка учеников?","url":"vydumka-voskreseniya.html","kind":"Вопрос","text":"Коротко Нет. Ученики были готовы умереть за то, что видели живого Иисуса. За выдумку, которую сам сочинил, так не умирают. Что признаёт большинство историков Большинство историков признаёт три вещи: Казнь — Иисуса казнили и похоронили. Пустая могила — через несколько дней она оказалась пустой. Встречи с Ним — ученики были уверены, что видели Его живым. И вера в воскресение быстро распространилась прямо в Иерусалиме, где каждый мог проверить. Если это обман После казни ученики прятались от страха. А потом вдруг стали бесстрашно говорить о воскресении и шли за это в тюрьму и на смерть. Умирают за ложь, в которую верят. Но никто не умирает за ложь, которую сам придумал. И если бы ученики сочиняли, вряд ли первыми свидетелями сделали бы женщин: их слову в то время в суде не верили. Если это видение Галлюцинация бывает у одного человека, а не у многих сразу. Павел пишет, что Иисус однажды явился","keys":"воскресение выдумка обман украли тело галлюцинация воскрес ли иисус правда ли воскресение доказательства пустая гробница воскресения учеников не умер на кресте миф","short":"Нет. Ученики были готовы умереть за то, что видели живого Иисуса. За выдумку, которую сам сочинил, так не умирают."},{"title":"Иисус правда вернётся?","url":"vtoroe-prishestvie.html","kind":"Вопрос","text":"Коротко Да. Иисус обещал вернуться, и христиане всех церквей в это верят. Когда это будет, не знает никто, поэтому все предсказания точных дат — ошибка. Обещание Иисуса Иисус обещал ученикам, что вернётся. А когда Он вознёсся на небо, ангелы сказали им: Он придёт снова. Тогда Он: будет судить мир ; воскресит умерших ; исправит всё сломанное . В это верят и православные, и католики, и протестанты. Даты не знает никто Иисус сказал прямо: О том дне и часе не знает никто. Иисус, Матфея 24:36 Поэтому, когда кто-то объявляет конец света на конкретное число, это не от Бога. Таких предсказаний было очень много. Ни одно не сбылось. Как к этому относиться Без страха и паники. Иисус сравнил это с хозяином, который уехал и может вернуться в любой момент. Хороший слуга не трясётся, а просто живёт так, чтобы не было стыдно. Для христиан это добрая новость: зло и боль не навсегда.","keys":"второе пришествие конец света апокалипсис иисус вернётся когда конец света страшный суд армагеддон антихрист будет 666 число зверя откровение последние времена мира скоро ли судный день","short":"Да. Иисус обещал вернуться, и христиане всех церквей в это верят. Когда это будет, не знает никто, поэтому все предсказания точных дат — ошибка."},{"title":"Чем Ветхий Завет отличается от Нового?","url":"vethiy-i-novyy.html","kind":"Вопрос","text":"Коротко Ветхий Завет — это книги, написанные до Иисуса: о сотворении мира, о народе Израиля и об обещании Спасителя. Новый Завет — книги об Иисусе и первых христианах. Для христиан это одна история: в первой части Бог обещает, во второй исполняет. Ветхий Завет Это большая часть Библии. В ней: Истории — сотворение мира, Авраам, Моисей, царь Давид. Псалмы — песни-молитвы. Пророки — слова, которые Бог передавал людям через них. Через всё это проходит одна мысль: Бог не оставил людей и пошлёт Того, Кто всё исправит. Новый Завет Это 27 книг: Четыре Евангелия — о жизни Иисуса. Деяния — о первых христианах. Письма апостолов — как жить с верой. Откровение — последняя книга: чем закончится история мира. Почему «Завет» Завет — это союз, договор между Богом и людьми. Старый союз Бог заключил с народом Израиля через Моисея. Новый — со всеми людьми через Иисуса. Зачем христианам обе части Без Ветхого","keys":"ветхий завет новый завет разница чем отличается две части библии старый завет зачем ветхий завет читать между ветхим и новым заветом ветхим новым","short":"Ветхий Завет — это книги, написанные до Иисуса: о сотворении мира, о народе Израиля и об обещании Спасителя. Новый Завет — книги об Иисусе и первых христианах. Для христиан это одна история: в первой части Бог обещает, во второй исполняет."},{"title":"Почему в Библии именно эти книги?","url":"kanon.html","kind":"Вопрос","text":"Коротко Книги не выбирали голосованием по вкусу. Церковь признала те книги, которые с самого начала читали как Слово Божье: написанные пророками, апостолами и их ближайшими учениками. Новый Завет Уже в первые десятилетия христиане читали на собраниях Евангелия и письма апостолов. Главный вопрос был простой: написано ли это апостолом или тем, кто знал апостолов? К IV веку список из 27 книг был общепринятым. Церковь не придумала его, а подтвердила то, что давно читали по всему миру. Ветхий Завет Ветхий Завет христиане приняли от иудеев. Иисус и апостолы читали эти книги как слово Бога. Здесь есть различие между церквями. В православной и католической Библии есть ещё несколько книг, написанных незадолго до Иисуса. Протестанты не включают их в Библию, хотя считают полезными для чтения. Почему не вошли другие Многие тексты, которые иногда называют «потерянными евангелиями», написаны через сто и ","keys":"канон библии почему эти книги кто выбирал книги библии кто составил библию неканонические книги сколько книг в библии какие будут решал выбрал апокрифы евангелие от иуды евангелие от фомы запрещенные спрятанные одни вошли а другие нет","short":"Книги не выбирали голосованием по вкусу. Церковь признала те книги, которые с самого начала читали как Слово Божье: написанные пророками, апостолами и их ближайшими учениками."},{"title":"Какой перевод Библии выбрать?","url":"perevody.html","kind":"Вопрос","text":"Коротко Для первого чтения лучше взять современный перевод: он написан понятным языком. Синодальный перевод красивый и самый известный, но многие слова в нём устарели. Синодальный перевод Это самый распространённый русский перевод, ему около 150 лет. Его читают и православные, и протестанты. Он точный и торжественный. Но язык XIX века местами труден: «дабы», «доколе», «ланиты». Новичку бывает сложно понять смысл. Современные переводы Есть переводы на обычный современный язык. Например: «Современный русский перевод» — Российского библейского общества; «Новый русский перевод» . Их делали знатоки древних языков. Читать их легче, а смысл тот же. Как поступить Начните с современного перевода, чтобы понять смысл. А когда захочется сравнить, откройте Синодальный: его выражения встречаются в книгах, песнях и в речи. Многие приложения для телефона позволяют читать несколько переводов рядом.","keys":"перевод библии какой перевод выбрать синодальный перевод современный перевод библия на современном языке рбо нрп какую библию купить какую библию читать сложный понятный","short":"Для первого чтения лучше взять современный перевод: он написан понятным языком. Синодальный перевод красивый и самый известный, но многие слова в нём устарели."},{"title":"Сбылись ли пророчества Библии?","url":"prorochestva.html","kind":"Вопрос","text":"Коротко Христиане верят, что да. Задолго до Иисуса пророки сказали, где Он родится, как будет страдать и что Его смерть будет за других. Всё это совпало с жизнью Иисуса. Что такое пророчество Пророк в Библии — это не гадалка. Это человек, через которого Бог говорил людям. Чаще всего пророки обличали зло и звали вернуться к Богу. Но иногда они говорили и о будущем, особенно о Том, Кого пошлёт Бог. Примеры Где родится — пророк Михей сказал: в маленьком Вифлееме. Как будет страдать — пророк Исаия писал о Слуге Божьем, Которого будут презирать, Который будет страдать за чужие грехи и будет похоронен с богатым. Что будет у креста — в одном из псалмов описано, как над страдающим смеются, делят его одежду и бросают о ней жребий. Всё это сбылось в жизни и казни Иисуса. А может, подстроили? Многое человек подстроить не может: где родиться, как тебя казнят, что сделают солдаты у креста. А древние ","keys":"пророчества сбылись ли пророчества предсказания библии исаия мессия предсказано пророки об иисусе библия предсказала иисуса предсказанное сбылось","short":"Христиане верят, что да. Задолго до Иисуса пророки сказали, где Он родится, как будет страдать и что Его смерть будет за других. Всё это совпало с жизнью Иисуса."},{"title":"Откуда у нас совесть?","url":"sovest.html","kind":"Вопрос","text":"Коротко Христиане верят, что совесть вложил в человека Бог. Это внутренний голос, который подсказывает, что хорошо, а что плохо. Он есть у всех людей, даже у тех, кто не верит в Бога. Закон в сердце Апостол Павел писал, что Божий закон написан у людей в сердцах. Поэтому даже те, кто никогда не читал Библию, знают, что нельзя предавать друга и мучить слабого. Во всех культурах люди чувствуют стыд и вину. Это след того, что мы созданы Богом. Совесть можно заглушить Человек, который привык ко злу, может почти не чувствовать вины. А бывает наоборот: совесть мучает за то, в чём человек не виноват. Её тоже нужно сверять с Богом. Что делать с виной Совесть говорит: ты виноват. Но она не может снять вину. Это может только прощение . Христиане верят: Бог прощает каждого, кто приходит к Нему через Иисуса. После этого совесть может успокоиться не потому, что вину забыли, а потому, что её простили.","keys":"совесть откуда совесть голос совести чувство вины стыд мораль откуда мы знаем что хорошо что плохо такое мучает угрызения а стыдно","short":"Христиане верят, что совесть вложил в человека Бог. Это внутренний голос, который подсказывает, что хорошо, а что плохо. Он есть у всех людей, даже у тех, кто не верит в Бога."},{"title":"Как простить того, кто причинил мне боль?","url":"prostit-drugih.html","kind":"Вопрос","text":"Коротко Простить — значит отказаться от мести и передать суд Богу. Это не значит сказать, что зло было нормальным, и не значит снова довериться тому, кто опасен. Часто прощение — не один момент, а путь. Чем прощение не является Это не забыть — простить не значит сделать вид, что ничего не было. Зло остаётся злом. Это не оставаться под ударом — прощение не требует быть рядом с тем, кто продолжает причинять вред. Можно простить и при этом защитить себя. Почему христиане прощают В молитве «Отче наш» есть слова: прости нам наши долги, как и мы прощаем нашим должникам. Бог простил нам огромный долг. Поэтому и нас Он зовёт прощать. Иисус, когда Его прибивали к кресту, молился о палачах: Отче, прости им, они не знают, что делают. Иисус, Луки 23:34 Если не получается Простить сразу бывает невозможно, особенно если рана глубокая. Можно начать с честной молитвы: Боже, я не могу простить, помоги мн","keys":"как простить обида простить обидчика не могу простить прощение других месть предательство простить родителей мужа жену друга измена предали муж изменил жена изменила обидели держу обиду отпустить обиду прощать всех отца мать","short":"Простить — значит отказаться от мести и передать суд Богу. Это не значит сказать, что зло было нормальным, и не значит снова довериться тому, кто опасен. Часто прощение — не один момент, а путь."},{"title":"Самоубийство — это грех, который нельзя простить?","url":"samoubiystvo.html","kind":"Вопрос","text":"Если вам сейчас очень тяжело Не оставайтесь с этим одни. Поговорите с близким человеком. Если есть мысли причинить себе вред, позвоните в службу экстренной психологической помощи вашей страны или по номеру 112. Коротко Нет, в Библии нет такого правила. Спасает человека Иисус, а не то, как закончилась его жизнь. Но жизнь — дар Бога, и Бог очень не хочет, чтобы кто-то её обрывал. Если вы думаете об этом Ваша боль настоящая, и Бог её видит. Но мысль, что выхода нет, — неправда, которую подсказывает боль. Сейчас главное не оставаться одному: скажите кому-нибудь, что вам плохо, позвоните на линию помощи. В Библии есть люди, которые просили Бога забрать их жизнь: пророк Илия, Иов. Бог не осудил их. Илии Он дал отдых и еду, а с Иовом говорил Сам. Если вы потеряли близкого Самоубийство часто связано с болезнью, депрессией, невыносимой болью. Судить человека может только Бог, а Он знает всё, что было у н","keys":"самоубийство суицид покончил с собой не хочу жить попадёт ли в ад самоубийца отпевание депрессия умереть самоубийцы попадают друг грех самоубийцей","short":"Нет, в Библии нет такого правила. Спасает человека Иисус, а не то, как закончилась его жизнь. Но жизнь — дар Бога, и Бог очень не хочет, чтобы кто-то её обрывал."},{"title":"Что такое семь смертных грехов?","url":"smertnye-grehi.html","kind":"Вопрос","text":"Коротко Это список из церковной традиции, а не из Библии: гордыня, жадность, зависть, гнев, блуд, чревоугодие и уныние. Его составили древние монахи, чтобы показать корни других грехов. Откуда список Ещё в IV–VI веках монахи заметили, что многие плохие поступки растут из нескольких корней. Так появился список главных страстей. В православной традиции их обычно восемь, в католической — семь. Есть ли «несмертные» грехи? Иногда кажется: есть страшные грехи, а есть мелкие, на которые можно не обращать внимания. Библия говорит строже: любой грех отделяет человека от Бога. Иисус сказал, что даже злоба в сердце сродни убийству. Так что грешны все, а не только убийцы. Хорошая новость Нет греха, который Бог не может простить тому, кто приходит к Нему. Иисус умер за все грехи, и «смертные», и «мелкие». Этот список полезен, чтобы честно посмотреть на себя. Но не чтобы бояться.","keys":"семь смертных грехов смертный грех гордыня зависть гнев уныние чревоугодие блуд жадность список грехов какие грехи смертные смертные грехи самые страшные грехи тяжкие грехи","short":"Это список из церковной традиции, а не из Библии: гордыня, жадность, зависть, гнев, блуд, чревоугодие и уныние. Его составили древние монахи, чтобы показать корни других грехов."},{"title":"Почему я делаю плохое, даже когда не хочу?","url":"pochemu-delayu-zlo.html","kind":"Вопрос","text":"Коротко Потому что грех — не только плохие поступки, но и сила внутри нас, которая тянет не туда. Это знакомо даже великим святым. Изменить это одной силой воли не получается, но Бог меняет человека изнутри. Вы не одни Апостол Павел, один из самых известных христиан, писал о себе: Я не делаю добро, которое хочу, а делаю зло, которого не хочу. Римлянам 7:19 То есть желать хорошего мало. Внутри что-то сломано, и это есть у каждого. Почему не помогает «просто взять себя в руки» Можно на время сдержаться. Но корень — в сердце: в гордости, обиде, страхе, в желании жить только для себя. Что делает Бог Когда человек доверяется Иисусу, Бог прощает его и даёт ему Святого Духа . Дух меняет желания изнутри, постепенно, иногда медленно. Христиане тоже срываются. Но каждый раз можно вернуться к Богу, попросить прощения и начать снова. Бог не устаёт прощать.","keys":"почему я делаю плохое не могу измениться срываюсь вредные привычки зависимость сила воли грех внутри не могу перестать бросить бросить курить курение обещаю себе и плохие справиться с собой бросить пить","short":"Потому что грех — не только плохие поступки, но и сила внутри нас, которая тянет не туда. Это знакомо даже великим святым. Изменить это одной силой воли не получается, но Бог меняет человека изнутри."},{"title":"Дьявол существует на самом деле?","url":"dyavol.html","kind":"Вопрос","text":"Коротко Да, христиане верят, что дьявол реален. Но он не второй бог и не равен Богу. Это ангел, который восстал против Бога. Иисус уже победил его, поэтому бояться его тем, кто с Богом, не нужно. Кто он Библия описывает дьявола как личность, а не просто как символ зла. Его называют сатаной, то есть противником, и отцом лжи. Он не создатель зла. Бог создал всех ангелов хорошими, но один из них из гордости восстал против Бога и увлёк других. Чем он занят Его главное оружие — ложь. Он нашёптывает: что Бог нас не любит; что грех безвреден; что прощения нет. Он не всемогущ, не всезнающ и не вездесущ. Он лишь творение и не может сделать больше, чем позволит Бог. Бояться ли его Иисус изгонял злых духов одним словом. На кресте Он лишил дьявола главной силы — права обвинять нас. Поэтому христиане не ищут бесов за каждым углом и не забывают о собственной ответственности. Но и не играют с оккультиз","keys":"дьявол сатана существует ли дьявол бесы демоны черти злые духи одержимость люцифер существуют демонов вселиться бес вселился кто такой откуда взялся падший ангел","short":"Да, христиане верят, что дьявол реален. Но он не второй бог и не равен Богу. Это ангел, который восстал против Бога. Иисус уже победил его, поэтому бояться его тем, кто с Богом, не нужно."},{"title":"От чего нас спасает Бог?","url":"ot-chego-spasenie.html","kind":"Вопрос","text":"Коротко От греха и того, к чему он ведёт: от вины, от разрыва с Богом и от смерти без надежды. А ещё Бог спасает не только «от», но и «для»: для жизни с Ним, которая начинается уже сейчас. Даже если всё нормально Человек может быть здоров, успешен и доволен. Но внутри у каждого есть то, что мы делали не так, и то, чего не исправить самому. Библия говорит, что грех отделяет нас от Бога, как стена. А без Бога у жизни нет прочной опоры, а у смерти — надежды. Кому нужна помощь Иисус говорил о Себе: Я пришёл не к здоровым, а к больным. Его помощь нужна тем, кто честно видит, что сам не справится. Спасение для чего Бог прощает вину и убирает стену между нами и Им. Человек получает: новую жизнь ; мир с Богом ; надежду на вечную жизнь . Это не только про «после смерти». Жизнь с Богом меняет человека уже здесь.","keys":"спасение от чего спасаться что значит спастись зачем мне спасение у меня всё нормально спасти от чего спасать хорошо человеку","short":"От греха и того, к чему он ведёт: от вины, от разрыва с Богом и от смерти без надежды. А ещё Бог спасает не только «от», но и «для»: для жизни с Ним, которая начинается уже сейчас."},{"title":"Что будет с теми, кто никогда не слышал об Иисусе?","url":"ne-slyshal.html","kind":"Вопрос","text":"Коротко Бог никого не отправляет в ад просто так. Каждому взрослому Он даёт возможность узнать о Нём, а решает человек сам. С детей Бог не спросит Маленький ребёнок ещё не понимает, что хорошо, а что плохо. Бог это знает и не судит его как взрослого. Взрослому Бог даёт возможность Бог хочет, чтобы каждый человек Его нашёл. Библия говорит, что Бог рядом с каждым человеком. Поэтому каждому взрослому Бог даёт возможность узнать о Нём: через совесть, через мир вокруг, через людей, которые расскажут об Иисусе. А дальше человек сам решает, принять Бога или нет. Бог судит честно Бог не спросит с человека того, чего тот не мог знать. А тот, кто уже услышал Если человек уже узнал об Иисусе, этот вопрос теперь и к нему: что он сам об Иисусе думает?","keys":"кто не слышал об иисусе язычники племена люди до христа другие религии справедливо ли погибнут ли не знали о боге знал слышали африке неверующие родные в ад родные попадут в ад неверующие родственники","short":"Бог никого не отправляет в ад просто так. Каждому взрослому Он даёт возможность узнать о Нём, а решает человек сам."},{"title":"Как понять, что Бог меня простил?","url":"uverennost.html","kind":"Вопрос","text":"Коротко Не по чувствам, а по Божьему обещанию. Бог обещал: кто доверяется Иисусу, тот прощён. Чувства приходят и уходят, а слово Бога остаётся. Чувства обманчивы Сегодня радостно, завтра тоскливо. Если судить о прощении по настроению, уверенности не будет никогда. Что обещает Бог Библия говорит: если мы признаём свои грехи, Бог, верный и справедливый, простит нас и очистит от всякого зла. И ещё: тех, кто доверился Иисусу, Бог больше не осуждает. Иисус сказал о тех, кто доверился Ему: «Никто не вырвет их из Моей руки» (Иоанна 10:28). Бог не просто прощает, Он больше не вспоминает прощённые грехи: «Я прощу их вину и больше не вспомню их грехов» (Иеремия 31:34). Прощение держится на том, что сделал Иисус, а не на том, насколько сильно мы раскаялись. Что меняется со временем Постепенно человек замечает перемены: ему хочется говорить с Богом ; ему больно от своего зла ; он начинает любить людей , которых раньше не выносил. Это не условие прощения, а его плод. Сомнения при этом бывают у всех, и это не значит, что Бог передумал.","keys":"простил ли меня бог как понять что уверенность в спасении не чувствую бога спасён я можно потерять спасение отпасть от веры однажды всегда спасен","short":"Не по чувствам, а по Божьему обещанию. Бог обещал: кто доверяется Иисусу, тот прощён. Чувства приходят и уходят, а слово Бога остаётся."},{"title":"Разве недостаточно просто верить, что Бог есть?","url":"vera-besov.html","kind":"Вопрос","text":"Коротко Нет, этого мало. Библия замечает: даже бесы верят, что Бог есть, и трепещут. Христианская вера — это не только согласие, что Бог существует, а доверие Ему. Знать и доверять — разное Вера в Библии — это когда опираешься на Бога всей жизнью, а не только соглашаешься с Ним в голове. Во что именно доверие Христианская вера — это доверие Иисусу: что Он умер за мои грехи и воскрес, и что Его прощение мне нужно. Вера видна по жизни Апостол Иаков писал: Вера без дел мертва. Иакова 2:26 Не потому, что дела спасают, а потому, что настоящее доверие меняет поступки.","keys":"просто верить что бог есть верю в бога но в душе бог в душе достаточно ли веры вера без дел бесы верят что-то что-то высшая сила по-своему не хожу церковь и не молюсь","short":"Нет, этого мало. Библия замечает: даже бесы верят, что Бог есть, и трепещут. Христианская вера — это не только согласие, что Бог существует, а доверие Ему."},{"title":"Кто такой Святой Дух?","url":"svyatoy-duh.html","kind":"Вопрос","text":"Коротко Святой Дух — это Бог, а не безличная сила или энергия. Христиане верят, что Он живёт в каждом, кто доверился Иисусу: утешает, учит и постепенно меняет человека изнутри. Он — Бог Христиане верят в одного Бога: Отца, Сына и Святого Духа. Святой Дух не меньше Отца и Сына. Это Троица . Его можно огорчить, Он говорит и учит. Это черты личности, а не силы вроде электричества. Обещание Иисуса Перед смертью Иисус сказал ученикам: Я не оставлю вас сиротами. Отец пошлёт вам Утешителя, Который будет с вами всегда. Иисус, Иоанна 14:16–18 Через пятьдесят дней после воскресения Святой Дух сошёл на учеников. Христиане вспоминают это в праздник Троицы, или Пятидесятницы. Что Он делает Объясняет — помогает понять Библию. Поддерживает — даёт силы, когда своих не хватает. Напоминает — что мы Божьи дети. Растит — в человеке любовь, радость, мир, терпение и доброту. Это происходит не мгновенно, а как","keys":"святой дух кто такой святой дух дух святой сила энергия троица пятидесятница утешитель это что такое","short":"Святой Дух — это Бог, а не безличная сила или энергия. Христиане верят, что Он живёт в каждом, кто доверился Иисусу: утешает, учит и постепенно меняет человека изнутри."},{"title":"Нужно ли христианину соблюдать посты?","url":"posty.html","kind":"Вопрос","text":"Коротко Пост — добровольный отказ от еды или чего-то привычного ради того, чтобы больше времени отдать Богу. Иисус постился и говорил о посте. Но спасает не пост, а Бог. Пост — не диета Цель поста не похудеть и не заслужить Божью любовь. Пост помогает увидеть, что Бог важнее даже хлеба. Вместо еды — молитва. Иисус постился сорок дней в пустыне прежде чем начал учить людей. Главное — сердце Иисус предупреждал: не поститесь напоказ, с печальным лицом, чтобы все видели. Пусть об этом знает Бог. А пророк Исаия писал, что Богу дороже другой пост: накормить голодного; помочь бедному; освободить угнетённого. Как в разных церквях В православной церкви есть календарь постов: Великий пост перед Пасхой, пост перед Рождеством и другие. Протестанты обычно постятся по собственному решению или вместе с церковью в особое время. Если у вас болезнь, беременность или вы принимаете лекарства, посоветуйтесь","keys":"пост посты нужно ли поститься великий пост зачем пост что есть в пост отказ от еды можно обязательно отказываться мяса мясо","short":"Пост — добровольный отказ от еды или чего-то привычного ради того, чтобы больше времени отдать Богу. Иисус постился и говорил о посте. Но спасает не пост, а Бог."},{"title":"Сколько денег нужно отдавать церкви?","url":"desyatina.html","kind":"Вопрос","text":"Коротко Никто не может заставить вас платить. В Новом Завете христиане дают добровольно, по возможности и с радостью. Многие ориентируются на десятую часть дохода, но это не плата за Божью любовь. Что такое десятина В Ветхом Завете израильтяне отдавали десятую часть урожая на храм, священников и бедных. Отсюда слово «десятина». Многие христиане и сегодня откладывают десятую часть на церковь и помощь людям. Но в Новом Завете нет строгой суммы. Как давать Пусть каждый даёт, как решил в сердце, не с огорчением и не по принуждению, потому что Бог любит того, кто дарит с радостью. Апостол Павел, 2 Коринфянам 9:7 Иисус особо похвалил бедную вдову, которая положила в храме две мелкие монетки. Для Бога важна не сумма, а сердце. Когда насторожиться Это повод уйти, если в церкви: требуют деньги под угрозой; обещают богатство и здоровье в обмен на пожертвование; не говорят , куда идут деньги. Божью","keys":"десятина деньги церкви пожертвования сколько платить в церкви десятая часть церковь требует деньги просит","short":"Никто не может заставить вас платить. В Новом Завете христиане дают добровольно, по возможности и с радостью. Многие ориентируются на десятую часть дохода, но это не плата за Божью любовь."},{"title":"Что христианство говорит о сексе до брака?","url":"seks-do-braka.html","kind":"Вопрос","text":"Коротко Христиане верят, что секс — хороший Божий подарок, и место ему в браке мужа и жены. Не потому, что Бог против удовольствия, а потому, что близость связывает людей глубже, чем нам кажется. Бог за, а не против В Библии есть целая книга, Песнь песней, — о любви и влечении мужчины и женщины. Бог Сам придумал близость, и в ней нет ничего постыдного. Но Библия говорит: двое становятся одним целым. Близость — это не только тело, а отдача себя. Почему именно в браке В браке, где двое пообещали друг другу верность, близость строит. Вне брака она часто оставляет раны. Брак даёт то, что нужно близости: обещание, доверие и уверенность, что тебя не бросят. Если уже было Многие читают это, когда у них уже была близость вне брака. Это не делает человека хуже других. Бог прощает и этот грех, как и любой другой. Иисус не осудил женщину, которую застали в измене. Он сказал ей: И Я не осуждаю тебя,","keys":"секс до брака добрачные отношения близость интим блуд гражданский брак сожительство девственность спать с парнем спать с девушкой свадьбы свадьбы жить вместе без без свадьбы","short":"Христиане верят, что секс — хороший Божий подарок, и место ему в браке мужа и жены. Не потому, что Бог против удовольствия, а потому, что близость связывает людей глубже, чем нам кажется."},{"title":"Можно ли христианину пить алкоголь?","url":"alkogol.html","kind":"Вопрос","text":"Коротко Библия не запрещает вино, но твёрдо запрещает пьянство. Многие церкви, особенно в России, советуют не пить совсем, чтобы не навредить себе и тем, кто борется с зависимостью. Вино в Библии Иисус на свадьбе превратил воду в вино. Вино было обычным напитком на праздниках. Но Библия много раз предупреждает: не напивайтесь, пьянство разрушает человека. Пьяницы названы среди тех, кто идёт против Бога. Почему многие не пьют совсем Многие евангельские христиане в России вообще не употребляют алкоголь. Причина простая: в стране, где пьянство губит столько семей, проще не начинать. Лучше не пить вина, если это может стать соблазном для брата. Апостол Павел, Римлянам 14:21 Любовь к людям важнее собственной свободы. Если есть зависимость Зависимость — не повод стыдиться и прятаться. Бог может освободить и от неё. Многие люди бросили пить, когда пришли к Богу и получили поддержку других христ","keys":"алкоголь можно ли пить вино пьянство христианин пьёт водка пиво зависимость алкоголизм трезвость христианам грех выпить выпивать","short":"Библия не запрещает вино, но твёрдо запрещает пьянство. Многие церкви, особенно в России, советуют не пить совсем, чтобы не навредить себе и тем, кто борется с зависимостью."},{"title":"Как понять, чего Бог хочет от меня?","url":"volya-boga.html","kind":"Вопрос","text":"Коротко Большую часть Божьей воли мы уже знаем: любить Бога и людей, быть честными, не делать зла. А в остальных решениях Бог даёт свободу и помогает через Библию, молитву, советы мудрых людей и обстоятельства. Многое уже сказано Бог уже ясно сказал главное: любите Меня и ближнего, говорите правду, прощайте, помогайте слабым. Если решение нарушает это, ответ ясен и без знаков. Свобода выбора В вопросах вроде профессии или города Бог часто не даёт одного «правильного» ответа. Можно спокойно выбрать то, что честно, мудро и полезно для других. Как Бог ведёт Через Библию — чем лучше её знаешь, тем лучше понимаешь, чего хочет Бог. Через молитву — можно просить мудрости, и Бог обещал её дать. Через советы — людей, которые знают вас и Бога. Не стоит гадать по случайно открытой странице или ждать чудесного знамения. Бог не играет с нами в угадайку.","keys":"воля божья чего бог хочет от меня как принять решение план бога на мою жизнь знак от бога призвание как понять волю бога узнать какой путь выбрать дает знаки знаки говорит ли с людьми голос говорит","short":"Большую часть Божьей воли мы уже знаем: любить Бога и людей, быть честными, не делать зла. А в остальных решениях Бог даёт свободу и помогает через Библию, молитву, советы мудрых людей и обстоятельства."},{"title":"Гороскопы, гадания и приметы — что в этом плохого?","url":"goroskopy.html","kind":"Вопрос","text":"Коротко Библия прямо запрещает гадания, колдовство и обращение к духам. Не потому, что Бог против интереса к будущему, а потому, что это доверие не Тому. Будущее в руках Бога, а не звёзд. Что говорит Библия В Ветхом Завете Бог много раз запрещает гадателей, колдунов и тех, кто вызывает умерших. В Новом Завете первые христиане сжигали свои колдовские книги, когда приходили к Иисусу. Почему это не безобидно Гороскоп кажется игрой. Но человек постепенно начинает искать опору в звёздах, картах или в чёрной кошке, а не в Боге. А гадания и спиритизм — уже не игра. Библия предупреждает, что за ними может стоять злая духовная сила, и советует держаться от этого подальше. Что вместо Христианину не нужно бояться ни тринадцатого числа, ни разбитого зеркала. Если Бог — любящий Отец, Который держит всё в Своих руках, то приметы теряют власть. Будущее можно не угадывать, а доверить Богу. Иисус говорил: Не беспокойтесь о","keys":"гороскопы гадания приметы астрология таро гадалка экстрасенсы магия колдовство порча сглаз суеверия верить в грех гадалке сходить к гадалке нумерология","short":"Библия прямо запрещает гадания, колдовство и обращение к духам. Не потому, что Бог против интереса к будущему, а потому, что это доверие не Тому. Будущее в руках Бога, а не звёзд."},{"title":"Вера — это для слабых людей?","url":"dlya-slabyh.html","kind":"Вопрос","text":"Коротко Нет. Вера — для честных людей, которые признают, что сами не справляются со всем. А это знают и сильные. Многие очень сильные и умные люди были верующими. Все мы слабее, чем кажемся Мы не можем отменить смерть, исправить прошлое или изменить своё сердце усилием воли. Признать это — не слабость, а трезвость. Иисус сказал: Я пришёл не к здоровым, а к больным. Христианство начинается с честности о себе. Верили и сильные Учёные Ньютон и Паскаль, писатель Достоевский, композитор Бах были верующими людьми. Их трудно назвать слабыми. Многие христиане шли на смерть за веру. Это требует больше силы, чем жить без неё. Вера требует мужества Это не лёгкий путь: простить врага ; говорить правду , когда выгоднее соврать; оставаться верным в браке. Вера — это не способ не думать. Это доверие Богу, у которого есть основания.","keys":"вера для слабых религия костыль самообман опиум для народа вера для слабаков умные люди не верят","short":"Нет. Вера — для честных людей, которые признают, что сами не справляются со всем. А это знают и сильные. Многие очень сильные и умные люди были верующими."},{"title":"Христианство — это сплошные запреты?","url":"zaprety.html","kind":"Вопрос","text":"Коротко Нет. В центре христианства не правила, а отношения с Богом, Который нас любит. Всё хорошее в мире создал Бог, и христиане этому радуются. Божьи запреты защищают нас, и уходит только то, что ранит вас и других. Сначала любовь Иисуса спросили, какая заповедь главная. Он ответил: люби Бога всем сердцем, а ближнего — как самого себя. Все остальные правила вырастают из этого. Всё хорошее — от Бога Бог создал мир и сказал, что он хорош. Дружба, музыка, вкусная еда, природа, смех, праздники — всё это Его подарки. Как это было Первое чудо Иисус сделал на свадьбе. Посреди праздника закончилось вино, и Он сделал так, чтобы праздник продолжился. Зачем «нельзя» Бог создал человека и знает, что его разрушает: ложь, зависть, измена, ненависть. Запреты защищают нас и других. Что на самом деле меняется Уходит то, что ранит — ложь, привычка срываться на близких, зависимости. О таком потом не жалеют. Друзья остаются — бросать их не нужно. Иисус Сам дружил с очень разными людьми. Появляется новое — прощение, покой на душе и Бог рядом. Жизнь с избытком Иисус сказал: Я пришёл, чтобы у людей была жизнь, и жизнь с избытком. Иисус, Иоанна 10:10","keys":"запреты христианство запрещает всё нельзя правила церкви почему скучная жизнь религия ограничения заповеди скучно бросить что радует друзья веселье праздники отказаться от жизни радость скучным все запрещено в христианстве запрещено придется все придется друзей христиане скучные если поверю придется менять","short":"Нет. В центре христианства не правила, а отношения с Богом, Который нас любит. Всё хорошее в мире создал Бог, и христиане этому радуются. Божьи запреты защищают нас, и уходит только то, что ранит вас и других."},{"title":"Зачем христианам иконы?","url":"ikony.html","kind":"Вопрос","text":"Коротко Икона — это изображение Иисуса, Марии или святых. Мы не молимся перед иконами, а обращаемся прямо к Богу через Иисуса. Почему мы молимся без икон В Библии есть заповедь: Не делай себе изображения, чтобы поклоняться ему. Исход 20:4–5 Мы опасаемся, что человек начнёт видеть силу в самом предмете. Поэтому в наших церквях обычно нет икон. Бог слышит молитву везде, и путь к Нему открыт через Иисуса. Картины не запрещены Картины на библейские сюжеты никто не запрещает. Они помогают вспомнить историю из Библии. Но молимся мы не им, а Богу. Главный образ Бога Главный образ Бога — Сам Иисус. Кто хочет узнать, какой Бог, может смотреть на Иисуса.","keys":"иконы почему протестанты не молятся иконам поклонение иконам почитание икон образа чудотворная икона идолы молиться без","short":"Икона — это изображение Иисуса, Марии или святых. Мы не молимся перед иконами, а обращаемся прямо к Богу через Иисуса."},{"title":"Что такое хула на Святого Духа?","url":"hula-na-duha.html","kind":"Вопрос","text":"Коротко Это когда человек ясно видит, что действует Бог, и всё равно упорно называет это злом и отвергает Бога до конца. Это не случайное плохое слово и не одна ошибка. Откуда эти слова Иисус исцелял людей и освобождал их от злых духов. Все видели, что это добро. Но религиозные учителя, которые Его ненавидели, сказали: Он делает это силой дьявола. Тогда Иисус и сказал, что Бог прощает людям любые грехи, кроме хулы на Святого Духа. Всякий грех и хула простятся человекам, а хула на Духа не простится человекам. Иисус, Матфея 12:31 Почему этот грех не прощается Святой Дух помогает человеку увидеть свой грех и прийти к Богу. Если человек сознательно и до конца отвергает Его, он сам закрывает себе дорогу к прощению. Бог не отказывается прощать. Это человек не хочет, чтобы его простили. Если вы боитесь, что совершили его Этот страх — хороший знак. Тот, кто сказал Богу окончательное «нет», о Бог","keys":"хула на святого духа хула на духа святого хулить духа непростительный грех грех который не прощается не простится вдруг я совершил боюсь что совершил хулил бога ругал бога проклял бога сказал плохое о боге оскорбил бога святой дух матфея 12","short":"Это когда человек ясно видит, что действует Бог, и всё равно упорно называет это злом и отвергает Бога до конца. Это не случайное плохое слово и не одна ошибка."},{"title":"А если я попробую поверить и ничего не почувствую?","url":"nichego-ne-chuvstvuyu.html","kind":"Вопрос","text":"Коротко Так бывает часто, и это не значит, что Бога нет или что Он вас не принял. Вера — это доверие Богу, а не особое чувство. Чувства приходят и уходят, а Бог остаётся рядом. Вера держится не на чувствах Одни люди, когда приходят к Богу, плачут от радости. Другие не чувствуют ничего особенного. Христиане верят, что Бог принимает человека, когда тот Ему доверяется, а не когда что-то почувствует. Бог обещал не отвергать того, кто к Нему приходит. Это обещание не зависит от настроения. Того, кто приходит ко Мне, Я не прогоню. Иисус, Иоанна 6:37 Что можно делать Читать Евангелие — так вы лучше узнаете Иисуса, и доверие будет расти. Говорить с Богом честно — в том числе о том, что вы ничего не чувствуете. Быть рядом с другими христианами — с ними легче расти в вере. Многие верующие говорят, что поняли, как Бог был рядом, только спустя время.","keys":"ничего не почувствую ничего не чувствую не чувствую бога не чувствую веры попробовал поверить не получилось не работает вера без чувств пустота нет эмоций бог молчит холодно на душе почувствовать бога ощутить бога пытался поверить ничего не изменилось не изменилось","short":"Так бывает часто, и это не значит, что Бога нет или что Он вас не принял. Вера — это доверие Богу, а не особое чувство. Чувства приходят и уходят, а Бог остаётся рядом."},{"title":"Может ли в человека вселиться бес?","url":"bes.html","kind":"Вопрос","text":"Коротко Библия говорит, что злые духи существуют и могут сильно мучить человека. Но Иисус сильнее их, и бояться их христианину не нужно. В человека, который принадлежит Иисусу, бес вселиться не может. Что говорит Библия В Евангелиях много раз рассказывается, как Иисус встречал людей, которых мучили злые духи. Он одним словом освобождал этих людей, и духи Его слушались. Иисус говорил о бесах как о настоящих злых существах, а не просто как о болезни. Христианину бояться не нужно Христиане верят: в том, кто доверился Иисусу, живёт Святой Дух. Там, где Бог, злой дух не может стать хозяином. Тот, Кто в вас, больше того, кто в мире. 1 Иоанна 4:4 Важно знать Не всё странное — от бесов — многие тяжёлые состояния — это болезни, и их лечат врачи. Обратиться к врачу — правильно и не стыдно. С оккультным лучше не играть — гадания, спиритизм и «вызов духов» открывают дверь тому злу, о котором говорит","keys":"бес бесы вселиться бес вселился вселение одержимость одержимый одержим бесноватый демон демоны вселиться в человека изгнание бесов экзорцизм отчитка злые духи нечистая сила нечисть порча","short":"Библия говорит, что злые духи существуют и могут сильно мучить человека. Но Иисус сильнее их, и бояться их христианину не нужно. В человека, который принадлежит Иисусу, бес вселиться не может."},{"title":"Грех ли просто думать о плохом?","url":"dumat-o-plohom.html","kind":"Вопрос","text":"Коротко Если плохая мысль просто пришла в голову — это ещё не грех. Грех начинается, когда человек держится за неё, наслаждается ею и мысленно её «проживает». Искушение — это не грех Плохие мысли приходят к каждому. Даже Иисуса искушали, но Он не согрешил. Значит, сама мысль, которая мелькнула, ещё не делает человека виноватым. Когда мысль становится грехом Иисус говорил, что грех начинается в сердце. Тот, кто долго злится на человека, уже нарушил заповедь «не убивай». А тот, кто смотрит на чужую жену или мужа с желанием, уже изменил в сердце. Богу важны не только поступки, но и то, что происходит у нас внутри. Что с этим делать Не пугаться — плохая мысль не делает вас «пропащим». Не задерживаться на ней — переключиться и сказать Богу: помоги мне. Просить прощения, если зашли далеко — Бог прощает и грехи мыслей.","keys":"думать о плохом плохие мысли грешные мысли грех в мыслях мысли грех ли думать навязчивые мысли искушение соблазн похоть в мыслях злиться в мыслях желать зла фантазии грязные мысли","short":"Если плохая мысль просто пришла в голову — это ещё не грех. Грех начинается, когда человек держится за неё, наслаждается ею и мысленно её «проживает»."},{"title":"Кто такой антихрист и что значит 666?","url":"antihrist.html","kind":"Вопрос","text":"Коротко Антихрист — это противник Христа. Библия говорит, что перед возвращением Иисуса появится человек, который будет обманывать людей и бороться с Богом. 666 — это его тайное число из книги Откровение. Но Иисус победит, и бояться христианам не нужно. Кто такой антихрист Слово «антихрист» значит «против Христа». Апостол Иоанн писал, что таких противников много уже сейчас: это все, кто учит, что Иисус — не Бог и не Спаситель. Но в конце времён, как говорит Библия, придёт главный противник. Он будет выдавать себя за спасителя, творить ложные чудеса и требовать, чтобы ему поклонялись. Что значит 666 В книге Откровение сказано, что у этого противника будет число 666. Что именно оно значит, христиане понимают по-разному. Многие учёные думают, что для первых читателей это был намёк на жестокого римского императора Нерона, который преследовал христиан. Точно известно одно: штрихкоды, ИНН и но","keys":"антихрист кто такой антихрист 666 число зверя печать зверя начертание зверя штрихкод штрих код инн чипы чипирование паспорт апокалипсис откровение последние времена конец света зверь","short":"Антихрист — это противник Христа. Библия говорит, что перед возвращением Иисуса появится человек, который будет обманывать людей и бороться с Богом. 666 — это его тайное число из книги Откровение. Но Иисус победит, и бояться христианам не нужно."},{"title":"Есть ли у меня ангел-хранитель?","url":"angel-hranitel.html","kind":"Вопрос","text":"Коротко Библия говорит, что ангелы существуют и Бог посылает их защищать людей. Есть ли у каждого человека свой личный ангел, Библия прямо не говорит. Но точно ясно: Бог заботится о вас Сам. Что Библия говорит об ангелах Ангелы — это духовные существа, которых создал Бог. Они служат Ему и помогают людям. В Библии ангелы выводят людей из беды, предупреждают об опасности и приносят вести от Бога. Он повелит Своим ангелам охранять тебя на всех твоих путях. Псалом 90:11 А личный ангел? Иисус однажды сказал про детей, что их ангелы всегда перед Богом. Поэтому в православии и католичестве верят, что у каждого человека есть свой ангел-хранитель. Протестанты обычно говорят осторожнее: Бог посылает ангелов, когда нужно, но точно утверждать, что у каждого есть «свой» ангел, Библия не позволяет. Главное Христиане молятся не ангелам, а Богу. Ангелы — Его слуги. А главная защита человека — это Сам Бо","keys":"ангел хранитель ангелхранитель ангелы ангел есть ли ангелы мой ангел личный ангел защищает ангелов охраняет ангелы существуют молиться ангелу","short":"Библия говорит, что ангелы существуют и Бог посылает их защищать людей. Есть ли у каждого человека свой личный ангел, Библия прямо не говорит. Но точно ясно: Бог заботится о вас Сам."},{"title":"Попадут ли животные в рай?","url":"zhivotnye-v-rayu.html","kind":"Вопрос","text":"Коротко Библия прямо об этом не говорит. Но она обещает, что на новой земле, которую создаст Бог, будут животные. Попадёт ли туда именно ваш питомец, мы не знаем. Зато знаем, что Бог любит Своё творение и не делает ничего жестокого. Бог любит животных Бог создал животных и назвал их хорошими. Иисус говорил, что даже маленькая птица не упадёт на землю без воли Божьей. Бог видит каждое живое существо. Животные в будущем мире Библия говорит, что в конце Бог не уничтожит мир, а обновит его. Пророк Исаия описывает этот мир так: волк будет жить рядом с ягнёнком, а лев есть солому, как бык. Значит, животные там будут, и они больше не будут вредить друг другу. А мой питомец? На этот вопрос Библия ответа не даёт, и честнее так и сказать. Но если вы скучаете по любимому животному, можно доверить это Богу. Он добрее, чем мы можем представить.","keys":"животные в раю животные в рай попадут ли животные питомец питомцы кошка кот собака пес умер питомец умерла собака умер кот душа у животных есть ли душа у животных встречу своего питомца","short":"Библия прямо об этом не говорит. Но она обещает, что на новой земле, которую создаст Бог, будут животные. Попадёт ли туда именно ваш питомец, мы не знаем. Зато знаем, что Бог любит Своё творение и не делает ничего жестокого."},{"title":"Зачем Богу, чтобы Ему поклонялись?","url":"zachem-poklonenie.html","kind":"Вопрос","text":"Коротко Богу наше поклонение не нужно — у Него и так всё есть. Оно нужно нам. Когда мы благодарим Бога и доверяем Ему, мы живём так, как задуманы: в правде о том, Кто главный. Бог не тщеславен Бог ни в чём не нуждается. Он не стал бы меньше, если бы никто Его не прославлял. Апостол Павел говорил, что Бог Сам даёт всем жизнь и всё необходимое. И Он не похож на гордого правителя, который любит лесть. Иисус, Сам будучи Богом, мыл ученикам ноги и отдал за людей жизнь. Что такое поклонение Это не только песни в церкви. Поклоняться Богу — значит ставить Его на первое место: любить, благодарить, слушаться и доверять Ему. Зачем это нам Человек всегда чему-то поклоняется: деньгам, успеху, другому человеку, себе. И всё это рано или поздно подводит. А Бог — единственный, Кто этого достоин и Кто не подведёт. Поэтому Он и зовёт людей к Себе.","keys":"поклонение поклоняться зачем богу поклонение зачем богу поклоняться прославлять бога славить хвала бог тщеславный бог эгоист богу нужна слава зачем петь богу зачем молиться богу хвалили хвалить","short":"Богу наше поклонение не нужно — у Него и так всё есть. Оно нужно нам. Когда мы благодарим Бога и доверяем Ему, мы живём так, как задуманы: в правде о том, Кто главный."},{"title":"Ноев ковчег и потоп — это правда было?","url":"noev-kovcheg.html","kind":"Вопрос","text":"Коротко Да, христиане верят, что потоп был на самом деле. Иисус говорил о Ное как о реальном человеке. Рассказы о великом потопе есть и у многих древних народов. Что произошло Библия рассказывает, что люди на земле стали очень злыми. Бог решил остановить зло потопом, но спас праведного Ноя, его семью и животных. Для этого Ной построил огромный корабль — ковчег. Почему христиане считают это правдой Так говорил Иисус — Он сравнивал Своё возвращение с днями Ноя, когда люди жили беспечно, пока не пришёл потоп. Об этом помнят многие народы — истории о великом потопе есть у древних шумеров, вавилонян и других народов. Ковчег описан точно — по размерам он был около 135 метров в длину, а его пропорции подходят для устойчивого корабля. Христиане по-разному понимают масштаб потопа: одни считают, что вода покрыла всю планету, другие — весь мир, известный людям того времени. Зачем эта история Она по","keys":"ноев ковчег ной ковчег потоп всемирный потоп великий потоп был ли потоп правда ли потоп нашли ковчег арарат радуга животные в ковчеге","short":"Да, христиане верят, что потоп был на самом деле. Иисус говорил о Ное как о реальном человеке. Рассказы о великом потопе есть и у многих древних народов."},{"title":"Сколько лет Земле по Библии и где там динозавры?","url":"vozrast-zemli.html","kind":"Вопрос","text":"Коротко Библия не называет возраст Земли. Христиане здесь расходятся: одни считают, что Земле несколько тысяч лет, другие согласны с учёными, что миллиарды. Динозавров Библия не упоминает, но они тоже часть творения Бога. Почему мнения разные В начале Библии сказано, что Бог создал мир за шесть дней. Одни христиане понимают это буквально и, складывая годы жизни людей из Библии, получают возраст Земли около 6–10 тысяч лет. Другие считают, что «день» в этом рассказе — это не 24 часа, а долгий период. Ведь Библия говорит, что у Бога тысяча лет — как один день. Такие христиане спокойно принимают научный возраст Земли. Что важно для всех христиан Спор идёт о том, как Бог творил. А в главном христиане согласны: мир не появился случайно, его создал Бог. А динозавры? Библия не перечисляет всех животных, которые когда-либо жили. Она рассказывает о Боге и людях, а не о палеонтологии. Динозавры — ч","keys":"возраст земли сколько лет земле сколько лет миру сколько лет вселенной 7000 лет 6000 лет миллиарды лет шесть дней творения дни творения динозавры динозавр динозаврах мамонты молодая земля","short":"Библия не называет возраст Земли. Христиане здесь расходятся: одни считают, что Земле несколько тысяч лет, другие согласны с учёными, что миллиарды. Динозавров Библия не упоминает, но они тоже часть творения Бога."},{"title":"Где был Иисус с 12 до 30 лет?","url":"iisus-12-30.html","kind":"Вопрос","text":"Коротко Жил дома, в Назарете. Он слушался родителей, рос и работал плотником. Истории о том, что Он ездил в Индию или Тибет, придумали в XIX веке, доказательств у них нет. Что говорит Библия Последний случай из детства Иисуса — когда в 12 лет Он остался в храме и беседовал с учителями. После этого Евангелие говорит коротко: Он вернулся с родителями в Назарет, слушался их и рос, становясь мудрее. Иосиф был плотником, и Иисус работал так же. Когда Он начал проповедовать, люди в Назарете удивлялись: разве это не тот плотник, которого мы все знаем? Почему об этих годах так мало написано Значит, в эти годы не происходило ничего необычного. Иисус жил как обычный человек: работал, помогал семье, ходил в синагогу. Евангелия — не биография, а рассказ о главном, поэтому они начинают с Его служения. А путешествия в Индию? Такие истории появились только в XIX веке. Ни один древний источник о них не ","keys":"иисус с 12 до 30 лет где был иисус молодость иисуса детство иисуса юность иисуса иисус в индии иисус в тибете путешествия иисуса потерянные годы плотник назарет чем занимался иисус до 30","short":"Жил дома, в Назарете. Он слушался родителей, рос и работал плотником. Истории о том, что Он ездил в Индию или Тибет, придумали в XIX веке, доказательств у них нет."},{"title":"Почему Иуда предал Иисуса?","url":"iuda.html","kind":"Вопрос","text":"Коротко Библия называет причины: Иуда любил деньги и поддался злу. Он продал Иисуса за тридцать серебряных монет. Потом он пожалел, но не вернулся к Богу, и это стало его трагедией. Кто такой Иуда Иуда был одним из двенадцати учеников Иисуса. Он три года ходил с Ним, видел Его чудеса и слушал Его. Ученики доверили ему общие деньги. Почему он предал Он любил деньги — Евангелие говорит, что Иуда был вором и брал из общих денег. Он впустил в сердце зло — Библия говорит, что в Иуду вошёл сатана, и Иуда сам на это согласился. Некоторые думают, что Иуда ещё и разочаровался: он ждал, что Иисус станет царём и выгонит римлян, а Иисус говорил о кресте. Но это лишь догадка. Чем всё закончилось Когда Иисуса осудили, Иуда пожалел о сделанном и вернул деньги. Но вместо того чтобы прийти к Богу за прощением, он покончил с собой. В ту же ночь Пётр трижды отрёкся от Иисуса. Но Пётр вернулся, и Иисус его ","keys":"иуда иуда искариот предательство иуды предал иисуса почему иуда предал тридцать серебренников 30 сребреников поцелуй иуды евангелие от иуды простил ли бог иуду","short":"Библия называет причины: Иуда любил деньги и поддался злу. Он продал Иисуса за тридцать серебряных монет. Потом он пожалел, но не вернулся к Богу, и это стало его трагедией."},{"title":"Почему именно евреи — избранный народ?","url":"izbrannyy-narod.html","kind":"Вопрос","text":"Коротко Бог выбрал этот народ не потому, что он был лучше других, а чтобы через него принести благо всему миру. Через евреев люди получили Библию, а потом пришёл Иисус. Теперь к Богу может прийти человек любого народа. Не за заслуги Бог выбрал Авраама и его потомков. Библия прямо говорит: не за то, что они были многочисленнее или лучше других. Бог выбрал их просто потому, что любил их. Избран — значит, у тебя есть задача Бог сказал Аврааму, что через него получат благословение все народы земли. Народ Израиля должен был хранить слово Бога и показывать миру, какой Он. Через них пришла Библия — почти все её книги написали евреи. Через них пришёл Иисус — Он родился евреем, как и Его ученики. А что сейчас? Через Иисуса дверь к Богу открыта для всех. Апостол Павел писал: во Христе нет разницы между евреем и не евреем, все одинаково дороги Богу. При этом Бог не разлюбил еврейский народ. И христ","keys":"избранный народ евреи израиль иудеи почему евреи богоизбранный народ избранность авраам почему бог выбрал евреев еврей","short":"Бог выбрал этот народ не потому, что он был лучше других, а чтобы через него принести благо всему миру. Через евреев люди получили Библию, а потом пришёл Иисус. Теперь к Богу может прийти человек любого народа."},{"title":"Можно ли злиться на Бога?","url":"zlitsya-na-boga.html","kind":"Вопрос","text":"Коротко Злость на Бога бывает у многих, особенно в горе. Говорить Богу о ней честно — можно. Он лучше примет честную боль, чем красивые слова, в которые вы сами не верите. В Библии на Бога жалуются Многие люди в Библии говорили Богу резкие слова. Иов, потеряв детей и здоровье, спрашивал, за что ему это. Давид в псалмах кричал: почему Ты меня оставил? Пророк Иеремия жаловался, что Бог его обманул. Бог не отвернулся ни от одного из них. Эти жалобы даже вошли в Библию. Почему это важно Когда человек злится на Бога и говорит Ему об этом, он всё ещё разговаривает с Богом. Это уже не равнодушие, а отношения, хоть и трудные. Но не оставаться в злости Злость можно принести Богу, но жить с ней долго тяжело. Тот же Иов в конце встретился с Богом и успокоился, хотя не получил ответа на все вопросы. Иногда понимание приходит не сразу, но мир в сердце возможен и раньше.","keys":"злиться на бога злюсь на бога обида на бога обижен на бога злость гнев на бога ненавижу бога бог несправедлив почему бог так со мной претензии к богу","short":"Злость на Бога бывает у многих, особенно в горе. Говорить Богу о ней честно — можно. Он лучше примет честную боль, чем красивые слова, в которые вы сами не верите."},{"title":"Можно ли молиться за умерших?","url":"molitva-za-umershih.html","kind":"Вопрос","text":"Коротко Православные и католики молятся за умерших. Протестанты этого не делают: мы верим, что судьба человека решается при жизни, и молитва после смерти её не меняет. Но молиться Богу о своём горе и благодарить Его за близкого человека можно и нужно. Почему протестанты не молятся за умерших Библия говорит, что человеку положено однажды умереть, а потом будет суд. Иисус рассказывал о богаче и нищем Лазаре: после смерти их судьбу уже нельзя было изменить. Поэтому протестанты считают, что выбор человека делается в этой жизни. А как Бог поступит с каждым, мы доверяем Ему: Он справедлив и милостив больше, чем мы. Что можно делать, когда умер близкий Благодарить Бога — за этого человека и за всё хорошее, что было. Говорить Богу о своей боли — Он утешает тех, кто плачет. Молиться за живых — за родных, которым сейчас тоже тяжело. Надежда Для тех, кто верит в Иисуса, смерть — не конец. Библия об","keys":"молиться за умерших молитва за умерших за усопших поминать поминки поминальная записка панихида сорок дней 40 дней девять дней родительская суббота отпевание умершие родные помочь умершему","short":"Православные и католики молятся за умерших. Протестанты этого не делают: мы верим, что судьба человека решается при жизни, и молитва после смерти её не меняет. Но молиться Богу о своём горе и благодарить Его за близкого человека можно и нужно."},{"title":"Можно ли христианину делать татуировки?","url":"tatuirovki.html","kind":"Вопрос","text":"Коротко Прямого запрета для христиан в Библии нет. Но перед тем как сделать татуировку, стоит честно ответить себе на пару вопросов: что на ней и зачем она мне. Откуда мнение, что нельзя В Ветхом Завете есть запрет делать на теле надрезы и знаки. Он был дан древнему Израилю. Тогда соседние народы резали и метили тело в знак скорби по умершим и в честь своих богов. Бог не хотел, чтобы Его народ перенимал эти обряды. Христиане не обязаны соблюдать обрядовые законы Ветхого Завета. Поэтому большинство церквей не считает татуировку грехом сама по себе. О чём стоит подумать Что изображено — символы других религий, магии или злые образы христианину не подходят. Зачем это мне — чтобы что-то кому-то доказать или привлечь к себе внимание? Или это просто красиво и что-то значит для вас? Это навсегда — то, что нравится в двадцать, может разонравиться в сорок. Библия говорит, что тело христианина — х","keys":"татуировки татуировка тату татушка тату грех делать татуировки пирсинг набить тату левит 19 верующему тату христианин с татуировкой","short":"Прямого запрета для христиан в Библии нет. Но перед тем как сделать татуировку, стоит честно ответить себе на пару вопросов: что на ней и зачем она мне."},{"title":"Можно ли христианину заниматься йогой?","url":"yoga.html","kind":"Вопрос","text":"Коротко Растяжка и упражнения для тела — не грех. Но у йоги есть и духовная часть, которая пришла из индуизма: мантры, приветствия божествам, медитации. Её христиане не принимают. Откуда пришла йога Йога появилась в Индии как духовная практика. Её цель — через упражнения и медитацию слиться с «высшим началом». То есть изначально это часть другой религии. Где граница Упражнения для тела — растяжка, дыхание и гибкость сами по себе нейтральны. Духовная часть — пение мантр, поклоны «солнцу», «открытие чакр» и медитации, где нужно опустошить ум, — это уже религиозная практика. Христиане по-разному решают этот вопрос. Одни спокойно ходят на занятия, где только упражнения. Другие отказываются от йоги совсем и выбирают обычную растяжку или пилатес. Главное Христианин молится Богу, а не ищет покой через техники. Если на занятии предлагают что-то духовное, можно спокойно в этом не участвовать.","keys":"йога йогой заниматься йогой медитация медитации мантры чакры растяжка пилатес восточные практики эзотерика медитировать медитация грех","short":"Растяжка и упражнения для тела — не грех. Но у йоги есть и духовная часть, которая пришла из индуизма: мантры, приветствия божествам, медитации. Её христиане не принимают."},{"title":"Христианам нельзя праздновать Хэллоуин?","url":"hellouin.html","kind":"Вопрос","text":"Коротко Библия о Хэллоуине ничего не говорит, поэтому христиане относятся к нему по-разному. Одни его не празднуют, потому что он прославляет смерть, ведьм и нечисть. Другие видят в нём просто костюмы и конфеты. Но заигрывать со злом христианину не стоит. Откуда этот праздник Хэллоуин вырос из древнего праздника кельтов. Они верили, что в эту ночь духи умерших приходят к живым. Позже на ту же дату пришёлся христианский День всех святых, а его канун по-английски и назывался Хэллоуином. Сегодня для большинства людей это просто весёлый вечер с костюмами. Почему многие христиане его не празднуют Главные образы Хэллоуина — смерть, ведьмы, демоны и страх. Библия говорит держаться подальше от колдовства и не играть со злом. Поэтому многие христиане решают не участвовать. Что выбрать Это решение каждый принимает по совести. Если всё же праздновать, лучше без «тёмных» костюмов и игр с духами. А м","keys":"хэллоуин хеллоуин halloween праздновать хэллоуин костюмы ведьмы тыква самайн день всех святых","short":"Библия о Хэллоуине ничего не говорит, поэтому христиане относятся к нему по-разному. Одни его не празднуют, потому что он прославляет смерть, ведьм и нечисть. Другие видят в нём просто костюмы и конфеты. Но заигрывать со злом христианину не стоит."},{"title":"Быть богатым — это грех?","url":"bogatstvo.html","kind":"Вопрос","text":"Коротко Нет, быть богатым — не грех. Грех — любить деньги больше Бога и людей. Библия предупреждает, что богатому это особенно легко. В Библии были богатые люди Авраам, Иов и царь Давид были очень богатыми, и Бог их любил. Среди друзей Иисуса тоже были состоятельные люди, которые помогали Ему. В чём опасность Корень всех зол есть сребролюбие. 1 Тимофею 6:10 Проблема не в деньгах, а в любви к ним. Иисус говорил, что богатому трудно войти в Царство Божье. Деньги легко становятся тем, на что человек надеется вместо Бога. Хочет ли Бог, чтобы у нас был достаток? Бог заботится о нас и хочет нам добра. Иисус учил просить у Бога хлеб на каждый день и говорил, что Отец знает, что нам нужно. Бог даёт людям то, что им действительно необходимо. Бог не хочет, чтобы человек жил в нужде и боялся завтрашнего дня. Но обещания, что каждый станет богатым, в Библии нет: одним Бог даёт больше, другим меньше.","keys":"богатство богатый богатым быть богатым деньги грех ли быть богатым много денег достаток бедность бедный евангелие процветания верблюд игольное ушко сребролюбие зарабатывать деньги зло деньги это зло","short":"Нет, быть богатым — не грех. Грех — любить деньги больше Бога и людей. Библия предупреждает, что богатому это особенно легко."},{"title":"Развод — это грех?","url":"razvod.html","kind":"Вопрос","text":"Коротко Бог задумал брак на всю жизнь, поэтому развод — это всегда боль и нарушение Его замысла. Но Библия называет случаи, когда развод допустим. И даже если развод был грехом, Бог прощает. Брак задуман навсегда Иисус говорил, что муж и жена становятся одним целым, и человек не должен разделять то, что соединил Бог. Поэтому Бог не хочет разводов: они ранят мужа, жену и детей. Когда развод допустим Измена — Иисус назвал её причиной, по которой развод возможен. Неверующий супруг уходит сам — апостол Павел писал, что тогда верующий не связан. Если в семье насилие, прежде всего важна безопасность. Бог не требует терпеть побои. Уйти и защитить себя и детей — правильно. Если развод уже был Развод — не клеймо на всю жизнь и не непростительный грех. Бог прощает тех, кто к Нему приходит, и помогает начать заново.","keys":"развод развестись развелись развод грех можно ли разводиться разведен разведена второй брак повторный брак измена мужа измена жены насилие в семье бьет муж расстаться","short":"Бог задумал брак на всю жизнь, поэтому развод — это всегда боль и нарушение Его замысла. Но Библия называет случаи, когда развод допустим. И даже если развод был грехом, Бог прощает."},{"title":"Можно ли встречаться с неверующим?","url":"vstrechatsya-s-neveruyushchim.html","kind":"Вопрос","text":"Коротко Библия советует христианам вступать в брак с верующими. А отношения обычно ведут к браку, поэтому многие христиане и встречаются только с верующими. Причина не в том, что неверующие хуже, а в том, что у пары должно совпадать самое главное. Что говорит Библия Апостол Павел писал христианам, чтобы они не связывали свою жизнь с теми, кто не верит. Вдова, по его словам, может снова выйти замуж, но только за верующего. Почему это важно Для христианина Бог — центр жизни. От этого зависит, как растить детей, на что тратить время и деньги, как решать трудности. Если для одного это главное, а для другого — нет, семье будет тяжело. А если уже в браке с неверующим? Тогда разводиться не нужно. Библия прямо говорит: если неверующий супруг хочет жить вместе, оставайтесь вместе. Любовь и пример верующего могут многое изменить в семье.","keys":"встречаться с неверующим неверующий парень неверующая девушка выйти замуж за неверующего жениться на неверующей брак с неверующим муж неверующий жена неверующая отношения с неверующим неравное ярмо парень не верит девушка не верит не верит в бога жена не верующая муж не верующий","short":"Библия советует христианам вступать в брак с верующими. А отношения обычно ведут к браку, поэтому многие христиане и встречаются только с верующими. Причина не в том, что неверующие хуже, а в том, что у пары должно совпадать самое главное."}]};